    "s4_frequency_load": "✦ Meuselwitz 2026 • Ladefrequenz synchronisiert...",
    "s4_notes": "Folie 4: Zeitleiste 140+ Jahre Tradition (9 Meilensteine). Besonderer Fokus auf Meilenstein 1 (1882: Gründung in Stuttgart – Beginn mit Klaviermechaniken; historische Parallele zu Carl Rönisch / Erfindung Voll-Panzerplatte 1866; Wurzel Meuselwitz), Meilenstein 2 (1906: Aufnahme der anspruchsvollen Hammerkopffertigung – Von Cristoforis lederbezogenem Papierröllchen 1700 zu Renners eigener Hammerkopfproduktion ab 1906, die später den Klang eines jeden Steinway-Flügels definierte und einen weltweiten Qualitätsstandard setzte; Bilderserie mit Cristofori, Hammer-Mechanik 1700, historischer Mechanikfertigung und Hammerkopfpressen 1906), Meilenstein 3 (1911: Technisierung & Flügelprogramm – Érard-Repetitionsmechanik als Basis des modernen Flügelspiels; Überleitung zur Aufnahme eigener Konzert-Flügelmechaniken bei Renner; Technisierung unter Oscar Renner mit neuzeitlichen Maschinen, arbeitssparenden Methoden und Umstellung von Transmissionen auf hunderte elektrische Einzelantriebe; Abrundung des Programms aus einer Hand; Bilderserie mit Sébastien Érard, 1808 Érard-Mechanik und elektrifizierter Arbeitsumgebung), Meilenstein 4 (1944: Brandnacht & Wiederaufbau), Meilenstein 5 (1951/1952: Dr. Manfred Renner; Wiederbezug 1955), Meilenstein 6 (1990: Mauerfall, Zeitenwende & Rettung des Fortbestands – Übernahme der Mechanik-Fertigung der Piano Union Zeitz im Wettbewerb mit tschechischen Herstellern und zur Sicherung des Großkunden Schimmel mit >40 Klavieren/Tag), Meilenstein 7 (2011: Der Neubau in Gärtringen und die neue moderne Fertigung in Meuselwitz nach dem Umzug von Zeitz nach Meuselwitz; Zusammenlegung an zwei festen Standorten: Meuselwitz 6.800 m² und Gärtringen; Bilderserie mit Neubau Gärtringen und Meuselwitz aus der Vogelperspektive), Meilenstein 8 (2019: Steinway & Sons Übernahme; Dank an Inhaber Clemens von Arnim) und Meilenstein 9 (Tradition bewahren. Zukunft gestalten: Vollendung der Bündelung aller Prozesse in Meuselwitz nach Projektstart Oktober 2025 mit neuer zentraler Filter- & Absauganlage; Dank an das Team Gärtringen).",
