    "s6_notes": "Folie 6: Die Firmengeschichte der Filzfabrik Wurzen (FFW) in Wurzen von 1783 bis heute und das Geheimnis des Weickert-Filzes. Stellen Sie die 6 historischen Meilensteine vor: 1783 Gründung in Wurzen durch J.D. Weickert, 1847 Erfindung des ersten deutschen Pianofortefilzes (Ablösung des Lederbezugs), 1850-1867 Weltausstellungen London & Paris mit königlichen Ehrungen, 1861 Großfertigung am Wurzener Mühlgraben mit Dampfmaschinen und dem weichen Mulde-Wasser, 1906 Weltmarktführer für 200.000 Klaviere jährlich (Steinway New York) und heute die Renaissance von 'Weickert Spezial' exklusiv für Louis Renner. Betonen Sie besonders die räumliche Nähe zwischen der Filzfabrik Wurzen und der Renner-Fabrik in Meuselwitz (nur ca. 65 km): Sie ermöglicht direkten Austausch zwischen den Filzmeistern und Hammerkopfmachern, kurze Wege und perfekte Qualitätsabstimmung.",
