    "s9_notes": "Folie 9: Die vier Säulen des Walkprozesses in Wurzen: Heißdampf, mechanischer Druck, oszillierende Bewegung und die Erfahrung der Filzmeister. Entscheidend ist der Verzicht auf jegliche Kunstharze oder chemische Bindemittel – nur weiches Muldental-Wasser, Wärme und Mechanik verhaken die Keratinschuppen dauerhaft elastisch.",
