    "s10_b3_badge": "AKUSTISCHE PERFEKTION",
    "s10_notes": "Folie 10: Erklären Sie die physikalische Grenze des reinen Naturwalkens: Bei maximal 56 % Verwalkdichte (entspricht 0,56 g/cm³ Rohdichte) berühren und verschlingen sich die Merinofasern optimal, ohne gequetscht oder gebrochen zu werden. Höhere Werte wären nur durch chemische Tränkung oder Überpressen erreichbar – auf Kosten der Elastizität und Klangwärme.",
