    "s13_c1_desc": "Schonende Rohwollwäsche und intensives Walken verbinden 56 % Maximaldichte mit erhöhtem Wollfettgehalt (STFI-Prüfbericht P2024 0903).",
    "s13_m1_val": "56 %",
    "s13_m1_lbl": "Max. Verwalkdichte",
