    "s13_bullet_1": "<strong>56 % Verwalkdichte:</strong> Höchste rein mechanisch erzielte Dichte (0,56 g/cm³) für starke Eigenspannung ohne chemische Härter.",
    "s13_bullet_2": "<strong>0,36 % Restfettanteil (ISO 3074):</strong> Schonende Wäsche erhält +38 % mehr natürliches Wollfett (ggü. 0,26 %) als Feuchteschutz.",
    "s13_bullet_3": "<strong>Geprüfte Klimastabilität:</strong> Im 48h-STFI-Wechselklimatest quillt der Filz um 65 % weniger (nur 4,81 % statt 13,69 % Dickenänderung).",
    "s13_bullet_4": "<strong>Intakte Schuppenschicht &amp; Intonation:</strong> Im REM sichtbare Epicuticula-Schuppen sichern hohe Fasertraktion und jahrelang konstante Klangfarbe.",
