    "s13_caption_1": "REM-Übersicht (STFI Mik59_24 • 1 mm): Hochverdichteter 3D-Faserverbund mit 56 % maximaler Verwalkdichte.",
    "s13_notes": "Folie 13: Weickert Special erzielt mit 56 % die höchste rein mechanisch erreichbare Verwalkdichte im Hammerkopffilz. Laut akkreditiertem STFI-Untersuchungsbericht P2024 0903 (Hr. Kermer, Juni 2024) bewahrt die schonende Rohwollwäsche einen höheren Restfettanteil von 0,36 % gegenüber 0,26 % (+38 % nach ISO 3074). Dadurch sinkt das Quellverhalten im 48h-Wechselklimatest um 65 % (nur 4,81 % statt 13,69 % Dickenänderung). Nutzen Sie den interaktiven REM-Zoom rechts, um stufenlos vom 1-mm-Faserverbund in die 100-µm-Einzelfasern und bis 25× auf die intakte Schuppenschicht hineinzuzoomen.",
    "s14_category": "Teil 3: Hammerkopf-Produktion • Filzvorbereitung",
