    "s14_b1_badge": "01 • 6-ACHS-ROBOTIK",
    "s14_c1_title": "Robotischer Deckfilz-Zuschnitt",
    "s14_bullet_1": "<strong>Streifenschnitt auf 1 mm:</strong> 6-Achs-Roboter teilt die gereiften konischen Filzplatten verzugsfrei über die gesamte Breite.",
    "s14_bullet_2": "<strong>Kaltschnitt ohne Quetschung:</strong> Scharfe Klingen trennen die Merinofasern glatt und ohne thermische Einwirkung.",
    "s14_bullet_3": "<strong>Inline-Chargencodierung:</strong> Eindeutige Platten- und Auftragsnummer auf jedem Streifen für lückenlose Rückverfolgbarkeit.",
    "s14_b2_badge": "DECKFILZ • 6-ACHS-SCHNITT",
    "s14_caption_1": "6-Achs-Roboter beim verzugsfreien Schneiden der Deckfilzstreifen",
    "s14_kpi_2": "± 0,1 mm Toleranz",
    "s14_b3_badge": "02 • PROFILFRÄSUNG",
    "s14_c2_title": "Profilfräsen des Unterfilzes",
    "s14_bullet_4": "<strong>Elastisches Bindeglied:</strong> Formgefräster Unterfilz überträgt den Anschlagimpuls vom harten Holzkern kontrolliert in den Deckfilz.",
    "s14_bullet_5": "<strong>Ausgefräste Schenkel (± 0,1 mm):</strong> Auf ± 0,1 mm genau gefräste Enden ermöglichen eine nahtlos geschlossene Hammerkontur bis in den Diskant.",
    "s14_bullet_6": "<strong>Symmetrischer Schließdruck:</strong> Das abgestimmte Keilprofil verteilt die Presskraft gleichmäßig in beide Hammerflanken.",
