    "s14_notes": "Folie 14: Beide Schritte der Filzvorbereitung im Überblick: Oben teilt der 6-Achs-Roboter die gereiften Filzplatten auf 1 mm genau verzugsfrei in chargencodierte Deckfilzstreifen; unten erhält der Unterfilzstreifen sein präzises Keilprofil als elastisches Bindeglied für symmetrischen Pressdruck.",
