    "s15_d4": "Schwer • Spezial",
    "s15_notes": "Folie 15: Die vier Renner-Kernhölzer im Vergleich: Weißbuche und Ahorn bilden die schweren Harthölzer – Weißbuche ist sehr aufwendig in der Trocknung, bei korrekter Trocknung aber ein ideales Kernholz; Ahorn kann elastischer sein, birgt durch unregelmäßige Zuckereinlagerungen jedoch höhere Abweichungsrisiken. Das eingesetzte Kotibé zählt durch seinen hohen Ölanteil ebenfalls zu den schwereren Hölzern und dient gezielten Spezialanwendungen. Das hochwertigste Holz ist feinjähriger, langfaseriger amerikanischer Nussbaum: extrem leicht und ideal für einen brillanten Diskant. Unten die symmetrischen Profile B, US, CSB sowie das asymmetrische Profil Form A.",
    "s16_category": "Teil 3: Hammerkopf-Produktion • Akustische Masse-Abstimmung",
    "s16_title": "Optimales Hammerkopfgewicht im Verhältnis zum Saitengewicht",
    "s16_subtitle": "Von ca. 15 g im Bass über den −1-g-Übergang bis 5 g im Diskant: Gleichgewicht aus Kontaktzeit und Saitenauslenkung",
