    "s16_ratio_tag": "Saitengewicht ↔ Hammermasse",
    "s16_principle_txt": "Passen <strong>Saitengewicht</strong> und <strong>Hammerkopfgewicht</strong> zusammen, stehen <strong>Kontaktzeit τc</strong> und <strong>Saitenauslenkung</strong> im idealen Gleichgewicht.",
    "s16_ctrl1_lbl": "1. Register & kritische Übergangszonen",
    "s16_zbtn_all": "✦ Gesamtregister (15 → 5 g)",
    "s16_zbtn_bass": "① Bass (~15 g lange hoch)",
    "s16_zbtn_break": "② Übergang Cu → Stahl (−1 g)",
    "s16_zbtn_treble": "③ Diskant (2 Okt. bis 5 g)",
    "s16_ctrl2_lbl": "Hammerkopfgewicht simulieren",
    "s16_wbtn_light": "🪶 Zu leicht",
    "s16_wbtn_opt": "⚖️ Gleichgewicht",
    "s16_wbtn_heavy": "⚓ Zu schwer",
    "s16_kpi1_lbl": "Kontaktzeit τc",
    "s16_kpi2_lbl": "Saitenauslenkung",
    "s16_kpi3_lbl": "Abstimmung",
    "s16_b3_badge": "✦ GEWICHTSABSTIMMUNG ÜBER ALLE 88 TASTEN",
    "s16_notes": "Folie 16: Entscheidend für Kontaktzeit τc und Saitenauslenkung ist das Verhältnis von Saitengewicht zu Hammerkopfgewicht. Im Bass startet der Hammerkopf bei ca. 15 g und bleibt über den kupferumsponnenen Bereich möglichst lange hoch (ca. 15–13 g), um die schweren Basssaiten voll auszulenken. Am Übergang auf die blanken Stahlsaiten sinkt das Saitengewicht abrupt – daher folgt hier ein gezielter 1-g-Sprung am Hammerkopf (13 g → 12 g), bevor die Masse in den letzten zwei Oktaven bis C8 auf 5 g ausläuft.",
    "s17_category": "Teil 3: Hammerkopf-Produktion • Leimpresse",
    "s17_title": "Pressen & Verleimen auf 0,1 mm",
    "s17_subtitle": "Aufbau von äußerer Zugspannung und innerer Stützkraft in der Leimpresse",
    "s17_kpi": "Toleranz 0,1 mm",
    "s17_b1_badge": "LEIMPRESSEN",
    "s17_c1_title": "Verpressen in Pressgesenk und temperierten Gegenlagen",
    "s17_c1_desc": "Präzisions-Leimpressen fügen Deckfilz, Unterfilz und Kernholz exakt reproduzierbar zusammen.",
    "s17_bullet_1": "<strong>Fertigungstoleranz 0,1 mm:</strong> Präzise geführte Gegenlagen sichern exakte Maßhaltigkeit über den gesamten Satz.",
    "s17_bullet_2": "<strong>Pressgesenk &amp; Gegenlagen:</strong> Der Filz wird nach unten in das Pressgesenk gedrückt; seitlich fahren dann die Gegenlagen zu und pressen den Filz an die Klebefläche.",
    "s17_bullet_3": "<strong>Definierte Spannungszonen:</strong> Hohe Zugkraft in der Außenhaut trifft auf einen komprimierten, elastischen Innenkern.",
    "s17_fact": "⚡ Dieses Spannungsgefälle bildet die Grundlage für Dynamik von pp bis ff",
    "s17_b2_badge": "WERKSVIDEO",
    "s17_caption_1": "Einpressen in das Pressgesenk und Schließen der Gegenlagen in Meuselwitz",
    "s17_notes": "Folie 17: In den Leimpressen fertigt Renner auf 0,1 mm genau. Zunächst wird der Filz nach unten in das Pressgesenk gedrückt; anschließend fahren von der Seite die temperierten Gegenlagen zu und drücken den Filz fest an die Klebefläche des Hammerkerns.",
    "s18_category": "Teil 3: Hammerkopf-Produktion • CNC-Fräsen & Kalibrieren",
