    "s18_subtitle": "Kernfräsung auf 0,1 mm, Nachfräsen nach dem Leimen und Kalibrieren jedes einzelnen Hammerkopfs auf der Roboteranlage",
    "s18_kpi": "Toleranz 0,1 mm",
    "s18_b1_badge": "CNC-FRÄSEN & ROBOTER",
    "s18_c1_title": "Zweistufiges CNC-Fräsen & Einzelkopf-Kalibrierung",
    "s18_c1_desc": "CNC-Fräsen bearbeiten erst die Hammerkerne und nach dem Leimen den Filzüberstand – danach kalibriert eine Roboteranlage jeden einzelnen Kopf.",
    "s18_bullet_1": "<strong>1. Hammerkerne fräsen (0,1 mm):</strong> Auf den CNC-Fräsen werden zunächst die Hammerkerne mit einer Toleranz von 0,1 mm präzise gefräst.",
    "s18_bullet_2": "<strong>2. Nachfräsen nach Pressen &amp; Leimen:</strong> Nach dem Verpressen und Verleimen wird der Filzüberstand abgetragen und sauber nachgefräst.",
    "s18_bullet_3": "<strong>3. Roboter-Kalibrierung:</strong> Im Anschluss wird auf einer Roboteranlage jeder einzelne Hammerkopf präzise kalibriert.",
    "s18_fact": "📐 0,1 mm Fräsgenauigkeit kombiniert mit reproduzierbarer Roboter-Kalibrierung am Einzelkopf",
    "s18_b2_badge": "WERKSVIDEOS",
    "s18_caption_1": "CNC-Fräszentrum & anschließende Einzelkopf-Kalibrierung auf der Roboteranlage",
    "s18_notes": "Folie 18: Auf den CNC-Fräsen werden zunächst mit einer Toleranz von 0,1 mm die Hammerkerne gefräst und nach dem Pressen und Leimen der Filzüberstand entfernt sowie die Kontur nachgefräst. Im Anschluss wird jeder einzelne Hammerkopf auf einer Roboteranlage präzise kalibriert.",
