    "s20_topic_5": "ZEITGEWINN",
    "s20_notes": "Folie 20: Betonen Sie das revolutionäre Highlight: Die fünfjährige Entwicklung eines proprietären Mess- und Fertigungssystems. Renner kann Hammerköpfe damit wiederholgenau auf ein exakt definiertes Klangspektrum fertigen. Das Ergebnis übertrifft den originalen Hammerkopf selbst in fabrikneuen Yamaha C1–C3 Flügeln und veredelt ältere wie neue Instrumente gleichermaßen – völlig ohne Intonation. Betonen Sie auch die Prozesssicherheit für Techniker, die nicht täglich intonieren: Das Kit nimmt jedes Risiko ab. Zusammen mit der 1-Schrauben-Montage und den unter hoher Vorspannung verleimten Röllchen sinkt die Arbeitszeit von 3–7 Tagen auf nur 4–5 Stunden bei überlegener Repetition. Zudem verbleibt das Instrument beim Kunden, und der Techniker gewinnt wertvolle Zeit, um das Instrument perfekt auf die Raumakustik und den individuellen Kundenwunsch abzustimmen.",
    "s21_category": "Teil 4: Yamaha Kit • Praxisbeweis Indien (1/2)",
    "s21_title": "Einbau im Zeitraffer: Komplettumbau an einem Tag",
    "s21_subtitle": "Dokumentation des taggleichen Einbaus (10:00 – 18:00 Uhr) direkt am Aufstellort in Indien (10/2026)",
    "s21_b1_badge": "ZEITRAFFER · 10–18 UHR",
    "s21_m1_unit": "Arbeitstag vor Ort",
    "s21_bullet_1": "<strong>Taggleicher Wechsel:</strong> Komplette Umrüstung auf das vorkonfektionierte Kit von 10:00 bis 18:00 Uhr.",
    "s21_bullet_2": "<strong>Plug &amp; Play Montage:</strong> Direktes Einschrauben der kalibrierten Kapseln ins originale Alu-Profil.",
    "s21_bullet_3": "<strong>Feinregulation vor Ort:</strong> Exaktes Einstellen von Steighöhe, Auslösung und Fang direkt am Flügel.",
    "s21_bullet_4": "<strong>Null Transportrisiko:</strong> Der Flügel bleibt im Raum und wird unmittelbar auf die Akustik abgestimmt.",
    "s21_kpi": "1 Arbeitstag",
    "s21_c1_title": "Kompletter Umbau direkt am Aufstellort",
    "s21_c1_desc": "Zeitraffer aus Indien (10–18 Uhr): Komplettumbau vor Ort inkl. Ausbau, Einbau, Regulation, Stimmung & Konzertprobe.",
    "s21_fact": "⏱ 10:00–18:00 Uhr: Vom Ausbau bis zum konzertfertigen Flügel vor Ort",
    "s21_notes": "Folie 21: Zeigen Sie das Zeitraffer-Video des kompletten Einbaus in Indien (10:00 bis 18:00 Uhr). Innerhalb eines einzigen Arbeitstages vor Ort wurde der Yamaha-Flügel vollständig auf das vorkonfektionierte Louis Renner Yamaha Kit umgerüstet und feinreguliert.",
