    "s22_c1_desc": "Pianistin Raaga prüft den umgerüsteten Yamaha-Flügel unmittelbar auf Klangwärme, Tragkraft und Spielart.",
    "s22_fact": "🎹 Sofort hörbarer Wandel zu europäischer Klangwärme und Kontrolle",
    "s22_notes": "Folie 22: Spielen Sie das Feedback-Video der Pianistin Raaga ab. Sie beschreibt unmittelbar nach dem Einbau des Louis Renner Yamaha Kits den deutlich wärmeren, singenden Konzertton sowie die feinfühlige Kontrolle vom Pianissimo bis zum Fortissimo.",
