    "s23_notes": "Auf dieser ersten Analyse-Folie sehen wir das hochauflösende Leistungsdichtespektrum L(f) der 11:42-minütigen Vergleichsaufnahme (0:00–5:17 Original-Hammerköpfe vs. 5:18–11:42 Louis Renner Yamaha Kit). Über die 2-Oktaven-Buttons oder direkt auf der 88-Tasten-Klaviatur lässt sich jedes beliebige 2-Oktaven-Fenster eingrenzen.",
