    "s24_notes": "Folie 24 schlüsselt für jedes 2-Oktaven-Fenster die Teiltonreihe von H1 (Grundton) bis H12 auf. Links sehen wir den Vergleich der 12 Harmonischen (umschaltbar zwischen Relativ zu H1, Delta-Gewinn und Absolutpegel), rechts die chromatische Einzelton-Auflösung aller 24 Halbtöne des gewählten 2-Oktaven-Bereichs.",
