    "s25_preset_dis7": "Dis₇ (2500 Hz)",
    "s25_notes": "Folie 25 fasst links die 4 quantifizierten Hauptvorteile des Louis Renner Yamaha Kits zusammen (+2,53 dB / +79 % im Gesangsregister, +1,87 dB / +54 % im Brillanzband, −3,28 dB Entmulmung im Bass sowie +0,93 dB/kHz flacherer Spectral Slope & +0,42 dB Crest). Rechts zeigt die Regressionsanalyse den Spectral Slope über der Anschlagsdynamik (pp–ff) samt Live-Rechner bis zur höchsten Klaviertaste C8 (4.186 Hz / max. 4.300 Hz).",
