    "s26_exp_badge": "✦ KLANGWIRKUNG",
    "s26_notes": "Folie 26 (Auftakt Kapitel 5: Intonation): Zeigen Sie interaktiv am tiefen A₁ (55 Hz, klingende Länge L = 1.560 mm), wie sich ein Klavierton aus seinen harmonischen Teiltönen H₁–H₁₂ zusammensetzt. Demonstrieren Sie zuerst die Tonhärte: Ein weicherer, genadelter Hammerkopf verlängert die Kontaktzeit τc (~3,8 ms) und senkt hohe Obertöne in dB ab, während ein härterer Scheitel (τc ~1,3 ms) hohe Teiltöne stark anhebt. Zeigen Sie danach am Saitenmodell das Young-Helmholtz-Gesetz: Bei 1/8 L bzw. 1/7 L dämpft der Hammer gezielt scharfe Reibungstöne (H₇ Naturseptime, H₉ Sekunde) im Schwingungsknoten ab, ohne die singende Dur-Terz H₅ (1/5 L) zu verlieren.",
    "s27_category": "Teil 5: Intonation • Federphysik, Verdichtungszonen & Dynamikgrenzen",
