    "s27_exp_badge": "✦ CRISTOFORI (1700)",
    "s27_notes": "Folie 27: Beginnen Sie mit 1. Cristofori-Röllchen (1700): Das hohle, belederte Pergamentröhrchen nutzt die Ringspannung ohne tote Innenmasse für hohe Rückstellkraft und kurze Kontaktzeit τc. Wechseln Sie dann auf 2. Renner-Spannungsfeder: Am Scheitel herrscht die höchste Verdichtung, an der breitesten Flanke die Hälfte (½), während die ungeschliffenen Fasern am Holzkern verleimt und vernietet sind. Zeigen Sie über die vier 3-Stufen-Schalter: Ist Scheitel oder Übergang zu hart, fehlt das Pianissimo; fehlt Elastizität oder sperrt die Schulter den Kraftfluss in die Flanke, verlängert sich τc und das Fortissimo bricht ein.",
    "s28_category": "Teil 5: Intonation • Faserverlauf, Nadelzonen & Klangwirkung",
