    "s28_kpi1_lbl": "Stichtiefe & Nadel",
    "s28_kpi2_lbl": "Oberflächenspannung",
    "s28_kpi3_lbl": "Klangeffekt",
    "s28_exp_badge": "✦ VORINTONATION • BLAUER FF-KEIL (9–10 / 2–3H)",
    "s28_notes": "Folie 28: Grundregel zuerst betonen: Wir orientieren uns beim Stechen immer am Faserverlauf des gewickelten Filzes und arbeiten in den oberen Zonen (9:00–3:00 Uhr) möglichst im Lot zur Faser (⊥, 90°), damit die Nadeln die gespannten Wollfasern nur sanft teilen statt sie schräg zu zerschneiden. Danach die Zonen live anklicken: 1. Blauer ff-Keil (9–10 / 2–3h, tief bis vor Unterfilz), 2. Grüner f-Keil (10–11 / 1–2h, 4–6 mm), 3. Oranger p-Keil (11–12 / 12–1h, 2,5–4 mm), 4. Violetter pp-Keil (≤ 2 mm, nur zwischen den Saitenrillen!). Als besonderen Aufbaustich 5. Oberhalb der Niete → Richtung Flanke zeigen: Hier setzt man bewusst WENIGE, aber TIEFE Stiche von knapp oberhalb der Niete steil aufwärts Richtung Flanke — das aktiviert die untere Spannreserve, steigert die Elastizität und hebt gezielt die hohen Teiltöne (H7–H12) an. 6. Rote Sperrzone (12:00 tiefer Kern = absolutes Tabu).",
    "s29_category": "Teil 5: Intonation • Geometrie im 3-chörigen Saitenbezug",
