    "s5_replay_btn": "↺ Replay Flipbook",
    "s5_drone_finale": "Drone Flight Finale",
    "s5_prev_btn": "Back",
    "s5_notes": "Slide 5: Chronological 14-phase construction record of the Meuselwitz plant conversion (11.2025 – 09.2026) during active production: gutting administration and foyer areas (Phases 1–2), underground utilities and wippen assembly line (Phases 3–4), vertical shuttle storage lifts (Phase 5), reinforced foundation and 70-ton crane installation of the 12 m, 120,000 m³/h extraction plant (Phases 6–8), relocation of hammerhead manufacturing (Phase 9), extraction ductwork, rooftop HVAC maintaining 45–50% RH year-round, and full consolidation of action and hammerhead production (Phases 10–14)—transitioning directly into the interior drone flight.",
    "s6_category": "Part 2: Felt Manufacturing • History & Tradition",
    "s6_title": "Filzfabrik Wurzen (FFW) – The Birthplace of Piano Hammer Felt",
    "s6_subtitle": "Wurzen 1783 • From the first piano felt in 1847 to the Weickert Spezial partnership with Renner",
