    "s6_m1_badge": "ORIGIN WURZEN 1783",
    "s6_m1_title": "Founding of the Felt Manufactory in Wurzen",
    "s6_m1_subtitle": "The world's oldest industrial felt manufactory – rooted in Saxony's Mulde valley",
    "s6_m1_bullet_1": "<strong>Founding in 1783:</strong> Johann Dankegott Weickert establishes the Saxon wool and felt tradition in Wurzen.",
    "s6_m1_bullet_2": "<strong>Fine Felt Pioneer:</strong> The artisan shop grows into a leading center for premium technical virgin wool felts.",
    "s6_m1_bullet_3": "<strong>Piano Focus:</strong> Early dedication to highly resilient felt for the emerging pianoforte industry.",
    "s6_m1_fact": "🏛 World's oldest industrial felt manufactory in Wurzen",
    "s6_m1_caption": "From hand-carded raw wool fleece to high-density top-felt sheets",
    "s6_m2_badge": "INVENTION 1847",
    "s6_m2_title": "Germany's First Viable Piano Hammer Felt",
    "s6_m2_subtitle": "Patzschke & Weickert revolutionize European piano craftsmanship in 1847",
    "s6_m2_bullet_1": "<strong>Felt Replaces Leather:</strong> In 1847, uneven leather hammer coverings are successfully replaced by homogeneous felt.",
    "s6_m2_bullet_2": "<strong>Strong Partnership:</strong> Weickert's enterprise and Patzschke's felt expertise establish international renown.",
    "s6_m2_bullet_3": "<strong>Soft River Water:</strong> The naturally soft, low-mineral Mulde water ensures pristine, resilient wool fibers.",
    "s6_m2_fact": "🎹 Milestone: Wurzen felt permanently replaces leather in pianos",
    "s6_m2_caption": "Golzernmühle near Grimma (1850): Early felt making on an island in the Mulde river",
    "s6_m3_badge": "LONDON & PARIS 1851",
    "s6_m3_title": "World Expos & Gold Medals in London & Paris",
    "s6_m3_subtitle": "International gold medals at the World Exhibitions in Leipzig, London, and Paris",
    "s6_m3_bullet_1": "<strong>World Expo Gold:</strong> Top honors in Leipzig (1850), London (1851), and Paris (1867) establish global acclaim.",
    "s6_m3_bullet_2": "<strong>Royal Visits:</strong> Saxon monarchs personally inspect and praise the superlative craftsmanship of the Wurzen mills.",
    "s6_m3_bullet_3": "<strong>Europe's Top Choice:</strong> Premier piano builders across Vienna, Paris, and London adopt Weickert felt exclusively.",
    "s6_m3_fact": "🏅 Gold Medals London 1851, Paris 1867 & Leipzig 1850",
    "s6_m3_caption": "Historical World Expo medals awarded for superlative felt excellence",
    "s6_m4_badge": "EXPANSION 1861",
    "s6_m4_title": "Industrial Scale at Mühlgraben in Wurzen",
    "s6_m4_subtitle": "Steam power, modern fulling mills, and the clean waters of the Mulde river",
    "s6_m4_bullet_1": "<strong>Industrial Scale:</strong> In 1861, modern facilities with proprietary steam power are erected at Wurzen's Mühlgraben.",
    "s6_m4_bullet_2": "<strong>Precision Fulling Mills:</strong> Steam-powered machinery guarantees unprecedented density and batch uniformity.",
    "s6_m4_bullet_3": "<strong>Gentle Wool Scouring:</strong> Mineral-poor river water preserves the natural cuticle scale structure of the Merino wool.",
    "s6_m4_fact": "⚙️ Steam fulling & natural river water at Wurzen Mühlgraben",
    "s6_m4_caption": "Original historical engraving of Pianofortefilzfabrik in Wurzen (1871)",
    "s6_m5_badge": "WORLD LEADER 1906",
    "s6_m5_title": "Global Market Leader for 200,000 Pianos Annually",
    "s6_m5_subtitle": "Director Patzschke, his master craftsmen & 350 specialists at Wurzen (1906)",
    "s6_m5_bullet_1": "<strong>Market Leader by 1906:</strong> Wurzen equips up to 200,000 pianos and grands worldwide with hammer felt each year.",
    "s6_m5_bullet_2": "<strong>Global Benchmark:</strong> Steinway & Sons New York and Europe's premier manufacturers rely on Wurzen felt.",
    "s6_m5_bullet_3": "<strong>Masters & Director Patzschke:</strong> Historic 1906 photograph standing before the monumental tapered felt block.",
    "s6_m5_fact": "🌎 Global reference standard for Steinway & Sons New York",
