    "s6_tab6_year": "Today",
    "s6_m6_year": "Today",
    "s6_notes": "Slide 6: Company history of Filzfabrik Wurzen (FFW) in Wurzen from 1783 to the present and the acoustic secret of Weickert felt. Introduce the 6 historical milestones: 1783 founding in Wurzen by J.D. Weickert, 1847 invention of Germany's first viable piano felt (replacing leather hammer covers), 1850-1867 London & Paris World Expos with royal honors, 1861 industrial expansion at Wurzen Mühlgraben with steam engines and soft Mulde water, 1906 world leader for 200,000 pianos annually (Steinway New York), and today the renaissance of 'Weickert Spezial' exclusively for Louis Renner. Strongly emphasize the close geographical proximity between Filzfabrik Wurzen and the Renner factory in Meuselwitz (just ~65 km): enabling direct master-to-master dialogue, resilient supply chains, and perfect acoustic tuning.",
    "s7_category": "Part 2: Felt Manufacturing • Raw Wool & Formula",
    "s7_title": "Pure Merino Wool & the Secret of Fiber Blending",
    "s7_subtitle": "Uncompressed overseas raw wool and tailored fiber recipes as the foundation of hammerhead felt",
    "s7_r1_step": "Stage 01",
    "s7_b1_badge": "RAW WOOL SELECTION",
    "s7_c1_title": "Uncompressed Overseas Merino Wool & Intact Fiber Structure",
    "s7_bullet_1": "<strong>Uncompressed Bale Delivery:</strong> Loosely packed shipping preserves the microscopic keratin scale structure intact.",
    "s7_bullet_2": "<strong>Pronounced Fiber Crimp:</strong> Millions of natural micro-springs ensure optimal interlocking during fulling and rapid rebound.",
    "s7_bullet_3": "<strong>Natural Lanolin:</strong> Pure wool grease and gentle scouring keep the keratin fibers supple for decades.",
    "s7_macro_tag": "FIBER MACRO",
    "s7_b2_badge": "UNCOMPRESSED RAW WOOL",
    "s7_caption_1": "Loosely delivered Merino wool retaining its strong natural fiber crimp",
    "s7_r2_step": "Stage 02",
    "s7_b3_badge": "FIBER FORMULA",
    "s7_c2_title": "Gentle Fiber Opening & Calibrated Blend Formula",
    "s7_m_bullet_1": "<strong>Calibrated Fiber Blend:</strong> Precise balance of long tensile fibers (for the crown) and fine filler wool (for core density).",
    "s7_m_bullet_2": "<strong>Multi-Stage Opening:</strong> Gentle plucking and pneumatic aeration separate fiber tufts cleanly into individual fibers.",
    "s7_m_bullet_3": "<strong>Climate Conditioning:</strong> Controlled moisture uptake prevents static charge, fiber breakage, and density spots.",
    "s7_b4_badge": "FFW BLENDING CHAMBER",
    "s7_caption_2": "Pneumatic loosening and blending of wool batches at FFW Wurzen",
    "s7_notes": "Slide 7: Combines the first two stages at FFW Wurzen: 1. Uncompressed, strongly crimped overseas Merino wool preserving keratin scales and lanolin; 2. The closely guarded blend of long tensile fibers and fine filler fibers in the pneumatic opening chamber.",
    "s8_category": "Part 2: Felt Manufacturing • Carding & Fiber Alignment",
    "s8_title": "Carding: Parallel Fiber Alignment into Fine Fleece Webs",
    "s8_subtitle": "Defined fiber orientation as the basis for uniform elasticity and predictable needle voicing",
    "s8_bullet_1": "<strong>Carding:</strong> Fine wire rollers gently comb the opened wool, untangling and aligning the fibers in parallel.",
    "s8_bullet_2": "<strong>Defined Fiber Course:</strong> The gossamer-thin fleece web receives a precisely controlled primary fiber direction.",
    "s8_bullet_3": "<strong>Controlled Layering:</strong> Superimposed fleece webs build target sheet thickness, tensile strength, and wedge taper.",
    "s8_bullet_4": "<strong>Foundation for Voicing:</strong> Only ordered fibers part cleanly and predictably when voiced with needles later on.",
    "s8_caption_1": "Carding Merino wool into uniform fleece webs with defined fiber alignment",
    "s8_b1_badge": "FIBER ORIENTATION",
    "s8_b2_badge": "CARDING & FLEECE",
    "s8_panel_title": "Drum cards comb fibers in parallel alignment",
    "s8_panel_subtitle": "Deliberate longitudinal and transversal alignment for predictable strike elasticity",
    "s8_fact_badge": "🧵 Parallel fiber guidance is the cornerstone of precise voicing",
    "s8_spotlight_badge": "FLEECE STRUCTURE",
    "s8_spotlight_title": "Prerequisite for Voicing",
    "s8_spotlight_desc": "Only parallel fibers respond predictably and uniformly to needle strokes in subsequent voicing",
    "s8_texture_tag": "Fleece Web: Ordered Fibers",
    "s8_hl1_title": "Gliding Needling:",
    "s8_hl1_desc": "Voicing needles part parallel fibers rather than severing them.",
    "s8_hl2_title": "Fluid Density Gradients:",
    "s8_hl2_desc": "Cross-layered stacking prevents delamination under extreme touch forces.",
    "s8_hl3_title": "Maximum Fiber Length:",
    "s8_hl3_desc": "Gentle carding prevents fiber breakage and ensures maximum tensile strength of the fleece.",
    "s8_b3_badge": "FLEECE STRUCTURE",
    "s8_c1_title": "Prerequisite for Voicing",
    "s8_c1_desc": "Only parallel aligned fibers respond predictably and uniformly to needle penetration during voicing",
    "s8_notes": "Slide 8: During carding, drum rollers comb the opened Merino wool into gossamer-thin webs with parallel fiber alignment. Emphasize the direct link to workshop practice: only because fiber orientation is established here can technicians later needle perpendicular to the fiber course with predictable results.",
    "s9_category": "Part 2: Felt Manufacturing • The Fulling Process",
    "s9_title": "The 4 Pillars of Fulling: Steam, Pressure, Motion & Experience",
    "s9_subtitle": "Purely mechanical-thermal fiber interlocking with soft Mulde water – 100% free from glues and resins",
    "s9_bullet_1": "<strong>1. Live Steam:</strong> Opens microscopic cuticle scales of fibers and renders keratin supple.",
    "s9_bullet_2": "<strong>2. Mechanical Pressure:</strong> Continuously compresses fleece layers, initiating progressive density increase.",
    "s9_bullet_3": "<strong>3. Oscillating Motion:</strong> Frictional rubbing interlocks natural barbed scales of fibers inextricably.",
    "s9_bullet_4": "<strong>4. Artisan Know-How:</strong> Sensory feel for the exact moment of completion governs elasticity and acoustic resonance.",
    "s9_c1_title": "1. Live Steam",
    "s9_c2_title": "2. Mechanical Pressure",
    "s9_c3_title": "3. Oscillating Motion",
    "s9_c4_title": "4. Master Experience",
    "s9_c1_desc": "Opens the microscopic cuticle scales of the wool fibers and renders the keratin supple.",
    "s9_c2_desc": "Compresses the layered fleece webs uniformly to initiate progressive densification.",
    "s9_c3_desc": "Rhythmic friction permanently interlocks the natural barbed scales of the fibers.",
    "s9_c4_desc": "Judging the exact stopping point governs natural springiness and overtone richness.",
    "s9_caption_1": "Fulling layered fleece webs under steam, pressure, and motion into a homogeneous felt sheet",
    "s9_b1_badge": "HOT STEAM",
    "s9_b2_badge": "MECHANICAL PRESSURE",
    "s9_b3_badge": "OSCILLATION",
    "s9_b4_badge": "CRAFTSMANSHIP",
    "s9_b5_badge": "HAMMER MILL",
    "s9_panel_title": "Pure mechanical felting without extraneous additives",
    "s9_panel_subtitle": "Water, heat, pressure, and rhythm permanently interlock fibers",
