    "s9_spotlight_badge": "FULLING COMPRESSION",
    "s9_spotlight_title": "Physical Compaction",
    "s9_spotlight_desc": "Scales of wool hairs interlock micromechanically like burrs",
    "s9_texture_tag": "Micro-Texture: Fulling Compression",
