    "s9_b6_badge": "CRAFTSMANSHIP",
    "s9_notes": "Slide 9: Present the four pillars of fulling at Wurzen: live steam, mechanical pressure, oscillating motion, and master experience. Highlight that zero synthetic resins or chemical binders are used—only soft Mulde valley water, heat, and mechanical action interlock the keratin scales with lasting elasticity.",
    "s10_category": "Part 2: Felt Manufacturing • Maximum Fulling Density",
    "s10_title": "56% Fulling Density (0.56 g/cm³): The Natural Limit of Mechanical Fulling",
    "s10_subtitle": "Maximum natural springback without fiber damage or chemical over-hardening",
    "s10_b1_badge": "PHYSICAL LIMIT",
    "s10_b2_badge": "FFW WURZEN",
    "s10_c1_title": "Maximum Natural Fulling Density of 56%",
    "s10_c1_desc": "During fulling, felt sheets are compacted until the wool fibers cannot be pushed closer purely mechanically—reaching a maximum fulling density of 56% (0.56 g/cm³).",
    "s10_caption_1": "Fulled tapered piano hammer felt sheets at Filzfabrik Wurzen",
    "s10_caption_2": "Post-fulling finishing of the mechanically fulled felt sheet in Wurzen",
    "s10_fact_badge": "🎯 Max. 56% Fulling Density (0.56 g/cm³): Peak elasticity with zero hardeners",
    "s10_spotlight_badge": "ACOUSTIC PERFECTION",
    "s10_spotlight_title": "Elastic Springback Instead of Brittle Hardness",
    "s10_spotlight_desc": "56% natural fulling density delivers brief string contact times and nuanced dynamic control.",
    "s10_texture_tag": "Natural Upper Limit: 56% Fulling Density (0.56 g/cm³)",
    "s10_hl1_title": "Rapid String Rebound:",
    "s10_hl1_desc": "The hammer rebounds instantly off strings without muting tone.",
    "s10_hl2_title": "Color-Rich Tone Spectrum:",
