    "s10_hl3_title": "Stable Hammer Action:",
    "s10_hl3_desc": "Consistent density sustained over tens of thousands of keystrokes.",
    "s10_panel_title": "Full Densification at the Physical Limit",
    "s10_panel_subtitle": "Felt sheets are compacted precisely to the point where fibers contact optimally",
    "s10_bullet_1": "<strong>Maximum Fiber Compression:</strong> Fibers cannot be mechanically compacted further without structural damage.",
    "s10_bullet_2": "<strong>Peak Natural Spring Rate:</strong> Corresponds to the physical optimum of inherent elasticity for concert grand touch.",
    "s10_bullet_3": "<strong>Free from Synthetic Resins:</strong> Eliminating chemical hardeners ensures permanent organic tone blooming.",
    "s10_b3_badge": "ACOUSTIC PERFECTION",
    "s10_notes": "Slide 10: Explain the physical ceiling of pure mechanical fulling: at a maximum fulling density of 56% (0.56 g/cm³), Merino fibers interlock at optimal closeness without crushing or breakage. Pushing beyond this would require chemical stiffeners or over-pressing at the expense of elasticity and tonal warmth.",
    "s11_category": "Part 2: Felt Manufacturing • Final Compaction & Layer Anatomy",
