    "s11_bullet_1": "<strong>Mechanical Hammering:</strong> Felt hammers and polished natural stones consolidate sheets to exact dimensions.",
    "s11_bullet_2": "<strong>Zero Sanding Removal:</strong> The Weickert process eliminates sanding completely—not a single tension fiber is cut.",
    "s11_bullet_3": "<strong>Unbroken Bending Radius:</strong> When pressed around the hammer moulding, the outer skin stays smooth and tear-free.",
