    "s13_notes": "Slide 13: Weickert Special achieves the highest purely mechanical fulling density of 56%. Per accredited STFI test report P2024 0903 (M. Kermer, June 2024), gentle scouring retains a higher residual wool grease content of 0.36% vs. 0.26% (+38%, ISO 3074), cutting humidity-cycle thickness swelling by 65% (only 4.81% vs. 13.69%). Use the interactive SEM zoom on the right to zoom smoothly from the 1 mm fiber network into the 100 µm single fibers and up to 25× onto the intact cuticle scales.",
