    "s20_topic_4": "TONE",
    "s20_topic_5": "TIME SAVED",
    "s20_notes": "Slide 20: Emphasize the core innovation: 5 years of R&D creating a proprietary measurement and production system. Renner produces hammerheads calibrated to a precise acoustic spectrum, outperforming factory hammers on brand-new Yamaha C1–C3 grands without voicing. Highlight the reassurance for technicians without daily voicing routine: the kit eliminates all risk. Together with 1-screw installation and pre-tensioned knuckles, workshop time drops from 3–7 days to just 4–5 hours on site with superior repetition. The piano stays with the customer, giving the technician time to fine-tune directly to the room acoustics and customer preferences.",
    "s21_category": "Part 4: Yamaha Kit • Field Proof India (1/2)",
    "s21_title": "Time-Lapse Installation: Complete Conversion in One Day",
    "s21_subtitle": "Documentation of the same-day installation (10:00 AM – 6:00 PM) on site in India (10/2026)",
    "s21_b1_badge": "TIMELAPSE · 10–18 H",
