    "s21_bullet_2": "<strong>Plug &amp; Play Fit:</strong> Direct mounting of pre-calibrated flanges and shanks onto the original rail.",
    "s21_bullet_3": "<strong>On-Site Regulation:</strong> Precise alignment, blow distance, let-off, and checking set right at the grand.",
    "s21_bullet_4": "<strong>Zero Transport Risk:</strong> The grand stays in place and is voiced directly to the room's acoustics.",
    "s21_kpi": "1 Workday",
    "s21_c1_title": "Complete Action Upgrade Directly On Site",
    "s21_c1_desc": "Time-lapse from India (10:00–18:00): Complete on-site conversion including removal, mounting, regulation, tuning & test play.",
    "s21_fact": "⏱ 10:00–18:00: From removal to a concert-ready grand on site",
    "s21_notes": "Slide 21: Show the time-lapse video of the complete installation in India (10:00 AM to 6:00 PM). Within a single workday on site, the Yamaha grand was completely converted and regulated with the pre-assembled Louis Renner Yamaha Kit.",
