    "s22_m1_unit": "Concert Tone Ex-Factory",
    "s22_bullet_1": "<strong>Singing Concert Tone:</strong> Audible shift from a hard attack to a warm, rich, projecting sound.",
    "s22_bullet_2": "<strong>Blooming Treble:</strong> Bell-like melody projection paired with clean chord clarity in the bass.",
