    "s25_preset_dis7": "D#₇ (2500 Hz)",
    "s25_notes": "Slide 25 summarizes on the left the 4 quantified core advantages of the Louis Renner Yamaha Kit (+2.53 dB / +79% in the singing register, +1.87 dB / +54% treble brilliance, −3.28 dB bass clarity, and a +0.93 dB/kHz flatter spectral slope & +0.42 dB crest). On the right, the scatter regression maps spectral slope across playing dynamics (pp–ff) alongside the live calculator up to C8 (4,186 Hz / max 4,300 Hz).",
    "s26_category": "Part 5: Voicing • Opening: Piano Tone Physics & Partials",
