    "s26_kpi2_sub": "330–660 Hz Brilliance",
    "s26_kpi3_lbl": "Node Suppression",
    "s26_exp_badge": "✦ TONAL EFFECT",
    "s26_notes": "Slide 26 (Chapter 5 Opening: Voicing): Interactively demonstrate on bass note A₁ (55 Hz, speaking length L = 1,560 mm) how a piano tone is built from partials H₁–H₁₂. First show felt hardness: a softer, needled hammer lengthens contact time τc (~3.8 ms) and reduces upper partials in dB, whereas a harder crown (τc ~1.3 ms) boosts upper partials sharply. Next demonstrate the Young-Helmholtz strike-point law: striking near 1/8 L or 1/7 L suppresses dissonant partials (H₇ natural seventh, H₉ major second) at their nodes while preserving the singing major third H₅ (1/5 L).",
    "s27_category": "Part 5: Voicing • Spring Physics, Compaction Zones & Dynamic Limits",
    "s27_title": "The Hammerhead as a Complex Spring: From Cristofori to Zone Balance",
    "s27_subtitle": "How elasticity, 2:1 compaction (crown → ½ flank), and shoulder transition govern playable dynamics (pp–ff)",
