    "s27_exp_badge": "✦ CRISTOFORI (1700)",
    "s27_notes": "Slide 27: Start with 1. Cristofori Roll (1700): the leather-covered hollow parchment cylinder uses circumferential ring tension with zero dead core mass for high restoring force and brief contact time τc. Then switch to 2. Renner Tension Spring: peak compaction sits at the crown, dropping to half (½) at the widest flank, anchored onto the hammer moulding by glue and rivet. Use the four 3-step controls to show that an overly hard crown/transition blocks pianissimo, while low elasticity or a locked shoulder prolongs τc and prevents fortissimo.",
    "s28_category": "Part 5: Voicing • Fiber Alignment, Needling Zones & Tonal Effect",
    "s28_title": "Voicing Zones & Needling Effect: The Renner Clock Model",
    "s28_subtitle": "Always perpendicular to the wool fiber (⊥): from the 9:00–3:00 wedges to the elasticity stitch above the rivet",
    "s28_pill_blue": "🔵 Blue (ff)",
    "s28_pill_green": "🟢 Green (f)",
