    "s28_z1_name": "🔵 Blue ff-Wedge (9–10 & 2–3h)",
    "s28_z1_depth": "Deep · ⊥ fiber",
    "s28_z1_desc": "Releases rigidity pre-underfelt, feeds f-wedge ↑ → open ff",
