    "s28_z3_depth": "2.5–4 mm · ⊥ fiber",
    "s28_z3_desc": "Cushions bright partials (H8–H12) → warm piano tone",
    "s28_z4_name": "🟣 Purple pp-Wedge (Crown)",
    "s28_z4_depth": "≤ 2 mm · grooves",
    "s28_z4_desc": "Between string grooves only (⊥ fiber)! Velvet cushion for pp",
    "s28_z_rivet_name": "🟡 Above Rivet → Toward Flank",
    "s28_z_rivet_depth": "Few · deep ↑",
    "s28_z_rivet_desc": "Few, deep stitches toward flank → boosts elasticity & high partials ↑",
    "s28_z5_name": "🔴 Red Taboo Zone (12:00 Core)",
    "s28_z5_depth": "✕ TABOO (> 2 mm)",
    "s28_z5_desc": "Severs tension arch σ → τc ↑, tone turns hollow & dead!",
    "s28_kpi1_lbl": "Needling Depth & Tool",
    "s28_kpi2_lbl": "Surface Tension",
    "s28_kpi3_lbl": "Tonal Effect",
    "s28_exp_badge": "✦ PRE-NEEDLING • BLUE FF-WEDGE (9–10 / 2–3H)",
    "s28_notes": "Slide 28: Start with the golden rule: always align with the wrapped wool fiber course and work perpendicular to the fiber (⊥, 90°) in the upper 9:00–3:00 wedges so needles part fibers cleanly rather than severing them diagonally. Walk through: 1. Blue ff-wedge, 2. Green f-wedge, 3. Orange p-wedge, 4. Purple pp-wedge (≤ 2 mm between grooves). Then highlight 5. Above the Rivet → Toward Flank: using FEW but DEEP stitches angled from just above the rivet upward toward the flank boosts spring elasticity, shortens τc, and strengthens upper partials (H7–H12). 6. Red 12:00 core taboo.",
    "s29_category": "Part 5: Voicing • Geometry in the 3-String Unison Choir",
    "s29_title": "Crown & String Plane in 3-String Choirs: Phase & Cancellation",
    "s29_subtitle": "Even a 0.2 mm height or angle mismatch causes phase cancellation notches across partials H₁–H₁₂",
    "s29_top_ideal": "✓ Flat & Parallel",
    "s29_top_tilted": "∠ Tilted Crown",
    "s29_top_uneven": "↕ Uneven String Plane",
    "s29_top_hollow": "⌣ Hollow Crown",
    "s29_btn_play": "Play A₃ Choir",
    "s29_sub1_lbl": "1 · Geometry: Crown ↔ 3-String Plane",
    "s29_sub1_tag": "Front View",
    "s29_sub2_lbl": "2 · Wave Superposition & Phase Shift",
    "s29_sub2_tag": "S₁ + S₂ + S₃ = Σ",
    "s29_b1_badge": "PARTIAL SPECTRUM",
    "s29_spec_title": "Effect on H₁–H₁₂ (A₃ · 220 Hz): Phase Cancellation Notches in dB",
    "s29_spec_hint": "Click bar for H₁–H₁₂",
    "s29_ctrl0_lbl": "Typical Alignment States in 3-String Choirs",
    "s29_pbtn_ideal": "✓ Flat & Parallel (Ideal)",
    "s29_pbtn_tilted": "∠ Tilted Crown",
