    "s33_b2_badge": "MEUSELWITZ PLANT",
    "s33_b3_badge": "LOUIS RENNER GMBH",
    "s33_c1_title": "Renner Academy Training Program",
    "s33_c1_desc": "In-depth workshops covering action geometry, hammerhead installation, Yamaha Kit mounting, and concert voicing.",
    "s33_bullet_1": "<strong>By Masters for Masters:</strong> Hands-on seminars built on authentic Renner factory specifications and gauges.",
    "s33_c2_title": "Factory Tours & Direct Technical Support",
    "s33_c2_desc": "Experience our unified production in Meuselwitz firsthand and rely on direct workshop support from our master team.",
    "s33_bullet_2": "<strong>Direct Master Dialogue:</strong> Meuselwitz factory visits, custom hammerhead sets &amp; personal technical consultation.",
