    "s2_notes": "スライド 2：モイゼルヴィッツ本社の担当者紹介です。経営全般およびパートナーシップ統括の最高経営責任者（CEO）エリック・シュティーラーと、モイゼルヴィッツ本社工場の責任者である工場長クレメンス・クナートをご紹介します。右上の「QR拡大表示」またはQRコードをクリックすると、会場後方からも読み取りやすい大型QR表示に切り替わります。",
