    "s3_c1_title": "歴史とモイゼルヴィッツ",
    "s3_c2_title": "ヴルツェン・フェルト製造",
    "s3_c3_title": "ハンマーヘッド製造",
    "s3_c4_title": "ヤマハ専用キット（C1–C3）",
    "s3_c5_title": "整音技術と質疑応答",
    "s3_c1_desc": "1882年創業からのアクション＆ハンマーヘッドの伝統、全工程を統合したモイゼルヴィッツ工場の建設記録とドローン映像。",
    "s3_c2_desc": "1783年創業のヴルツェン工場、高品質な羊毛配合、梳毛、緻密な縮絨密度、そしてフェルト原反をあえて研磨しないことの効果。",
    "s3_c3_desc": "フェルト保管、ヴァイケルト・スペシャルのSEM解析、裁断、コア材と重量設計、プレスと接着、CNC輪郭切削と高精度な表面仕上げ、リベット留めと穴あけ。",
    "s3_c4_desc": "C1–C3専用の即装着キット（現地4〜5時間）、取付タイムラプス、ピアニスト評価、音響スペクトル比較（H₁–H₁₂〜C₈）。",
    "s3_c5_desc": "A₁倍音構造、複合スプリング、整音モデル、クラウンと弦平面、仕上げ整音、硬化・アイロン処理、アカデミー＆質疑応答。",
    "s3_open_chapter": "章を開く",
    "s3_notes": "スライド 3：全5章の構成をご案内します。第1章：歴史とモイゼルヴィッツ工場（スライド 4–5）、第2章：ヴルツェンでのフェルト製造（スライド 6–11）、第3章：ハンマーヘッド製造工程（スライド 12–19）、第4章：ルイ・レンナー・ヤマハキット C1–C3 と音響解析（スライド 20–25）、第5章：コンサート整音と質疑応答（スライド 26–34）。各カードをクリックして直接移動できます。",
    "s4_category": "第1部：序論と歴史 • 企業年表",
    "s4_title": "140余年の伝統と精密技術（1882年〜現在）",
    "s4_subtitle": "シュトゥットガルトの手工業工房からピアノアクション＆ハンマーヘッドの世界基準へ",
    "s4_frequency_load": "✦ モイゼルヴィッツ 2026 • タイムライン同期中...",
    "s4_notes": "スライド 4: 140余年の歴史年表（全9節目）。注目は節目1（1882年：シュトゥットガルト創業 — ホイシュタイグ通りの工房でアクションから始まった歴史；カール・レーニッシュ総鉄骨フレーム革新との呼応）、節目2（1906年：自社ハンマーヘッド製造開始 — 1700年のクリストフォリによる革巻き紙ロールから1906年のレンナー自社生産へ。後にすべてのスタインウェイの響きを決定づけ世界基準を確立；クリストフォリ、1700年アクション、歴史的機械製造、1906年プレス機画像シリーズ）、節目3（1911年：電化革命とグランドピアノ機構 — エラールのレペティション機構を礎とする近代グランド演奏；レンナー初のグランド用アクション自社製造への飛躍；オスカー・レンナーによる最新工作機械・省力化工法・総軸から数百基の独立電動モーターへの転換；全工程の内製化；エラール、1808年機構、電化工房画像シリーズ）、節目4（1944年空襲と再建）、節目5（1951/1952年：マンフレート・レンナー博士）、節目6（1990年：ベルリンの壁崩壊と存亡を賭けたツァイツ工場買収 — チェコ製メーカー台頭の中で1日40台以上を生産する最大顧客シンメル社を守り抜いた歴史的転換点）、節目7（2011年：ゲルトリンゲン新社屋とツァイツからモイゼルヴィッツへの移転・最新生産拠点展開；2大拠点体制の確立；ゲルトリンゲン新社屋と上空からのモイゼルヴィッツ拠点画像シリーズ）、節目8（2019年：スタインウェイ買収と故アルニム氏追悼）、そして節目9（伝統を守り未来を創る：2025年10月始動の全プロセス・モイゼルヴィッツ統合完了と最新の集中集塵・排気フィルター設備導入、ゲルトリンゲン社員への深謝）。",
    "s5_category": "第1部：序論と歴史 • モイゼルヴィッツ工場改修",
    "s5_title": "建設ドキュメント：モイゼルヴィッツ統合工場の誕生",
    "s5_subtitle": "時系列フォトジャーニー（2025年11月〜2026年9月）と製造現場の屋内ドローン映像",
