    "s5_drone_title": "完成したモイゼルヴィッツ新工場 — ドローン空撮ツアー",
    "s5_replay_btn": "↺ パラパラ映像を再生",
    "s5_drone_finale": "ドローン映像フィナーレ",
    "s5_prev_btn": "前へ",
    "s5_notes": "スライド 5：稼働を止めずに進められたモイゼルヴィッツ工場改修の全14段階（2025年11月〜2026年9月）：管理棟・ロビー解体（第1〜2段階）、配管工事とウィッペン製造ライン新設（第3〜4段階）、垂直自動倉庫導入（第5段階）、高さ12m・風量120,000 m³/h集塵設備の基礎工事と70tクレーン据付（第6〜8段階）、ハンマーヘッド製造部門の移転（第9段階）、集塵ダクト網・年間湿度45〜50%を維持する屋上空調・全製造部門の統合完了（第10〜14段階）を経て、完成工場内部のドローン映像へ移行します。",
    "s6_category": "第2部：フェルト製造 • 歴史と伝統",
    "s6_title": "ヴルツェンフェルト工場（FFW）– ピアノハンマーフェルトの生誕地",
    "s6_subtitle": "ヴルツェン創業（1783年）• 1847年初のピアノフェルトからレンナー専用「ヴァイケルト特級」提携まで",
    "s6_play_label": "タイムトラベル再生",
