    "s6_m1_badge": "ヴルツェン起源 1783",
    "s6_m1_title": "ヴルツェンにおけるフェルト製造所の創業",
    "s6_m1_subtitle": "世界最古の工業フェルト製造所 — ザクセン州ムルデ渓谷に息づく伝統",
    "s6_m1_bullet_1": "<strong>1783年創業：</strong>ヨハン・ダンケゴット・ヴァイケルトがヴルツェンにザクセンの羊毛・フェルト伝統を確立。",
    "s6_m1_bullet_2": "<strong>高級フェルトの開拓者：</strong>手工業工房から技術用・音響用高級ウールフェルトの主要拠点へと発展。",
    "s6_m1_bullet_3": "<strong>ピアノ製造への特化：</strong>台頭するフォルテピアノのために高弾性打弦フェルトの開発へいち早く注力。",
    "s6_m1_fact": "🏛 ヴルツェンに息づく世界最古の工業フェルト製造所",
    "s6_m1_caption": "手梳きの原毛フリースから高密度トップフェルト原反へ",
    "s6_m2_badge": "発明 1847",
    "s6_m2_title": "ドイツ初の実用ピアノハンマーフェルト開発",
    "s6_m2_subtitle": "パチュケとヴァイケルトが1847年に欧州ピアノ製造の常識を刷新",
    "s6_m2_bullet_1": "<strong>革からフェルトへ：</strong>1847年、従来の硬い革巻きを均質な専用ハンマーフェルトに置き換えることに初成功。",
    "s6_m2_bullet_2": "<strong>技術と経営の融合：</strong>ヴァイケルトの企業力とパチュケの製フェルト技術が国際的評価を確立。",
    "s6_m2_bullet_3": "<strong>ムルデ川の地の利：</strong>ミネラル分の極めて少ない軟水が、極めて高純度で弾力に富むフェルトを育成。",
    "s6_m2_fact": "🎹 歴史的節目：ヴルツェン製フェルトがピアノの革巻きを置換",
    "s6_m2_caption": "ゴルツェルン水車小屋（1850年）：ムルデ川の中州で始まった初期フェルト製造",
    "s6_m3_badge": "万博金賞 1851",
    "s6_m3_title": "ロンドン・パリ万国博覧会での金メダル獲得",
    "s6_m3_subtitle": "ライプツィヒ・ロンドン・パリ万国博覧会での最高賞受賞",
    "s6_m3_bullet_1": "<strong>万博での金賞：</strong>ライプツィヒ（1850）、ロンドン（1851）、パリ（1867）での最高賞が世界的名声を確立。",
    "s6_m3_bullet_2": "<strong>国王親訪：</strong>ザクセン国王自らが工場を訪問し、ヴルツェン製フェルトの卓越した品質を親しく称賛。",
    "s6_m3_bullet_3": "<strong>欧州の第一選択：</strong>ウィーン、パリ、ロンドンの主要ピアノ工房がこぞってヴァイケルト製を採用。",
    "s6_m3_fact": "🏅 ロンドン1851、パリ1867、ライプツィヒ1850 金メダル",
    "s6_m3_caption": "極上のフェルト品質に対して授与された万国博覧会メダル",
    "s6_m4_badge": "拡張 1861",
    "s6_m4_title": "ヴルツェンのミュールグラーベン大工場へ拡張",
    "s6_m4_subtitle": "蒸気機関、最新鋭縮絨機、ムルデ川の清流が生む最高水準",
    "s6_m4_bullet_1": "<strong>大規模近代工場：</strong>1861年、ヴルツェンのミュールグラーベン水路沿いに自家蒸気動力の近代工場を建設。",
    "s6_m4_bullet_2": "<strong>高精度縮絨機：</strong>蒸気駆動の専用機械により、比類のないフェルト密度と均一な品質再現性を達成。",
    "s6_m4_bullet_3": "<strong>繊維を守る水質：</strong>ミネラル分の少ないムルデ川の清流がメリノウールの微細なキューティクルを完全保護。",
    "s6_m4_fact": "⚙️ ヴルツェン・ミュールグラーベンでの蒸気縮絨と天然清流",
    "s6_m4_caption": "1871年のヴルツェン・ピアノフェルト工場の歴史的景観",
    "s6_m5_badge": "世界首位 1906",
    "s6_m5_title": "年間20万台のピアノ用フェルトを生産する世界的首位",
    "s6_m5_subtitle": "パチュケ社長、熟練マイスター陣と350名の工匠（1906年）",
    "s6_m5_bullet_1": "<strong>世界シェア首位：</strong>年間20万台におよぶ世界中のアップライト・グランドピアノへハンマーフェルトを供給。",
    "s6_m5_bullet_2": "<strong>世界基準の確立：</strong>スタインウェイ・ニューヨークをはじめ欧州最高峰の全ピアノ工房が採用。",
    "s6_m5_bullet_3": "<strong>熟練技師とパチュケ社長：</strong>1906年の貴重写真：巨大なテーパー形状の縮絨フェルトブロックを囲む記念撮影。",
    "s6_m5_fact": "🌎 スタインウェイ・ニューヨーク御用達の世界基準",
    "s6_m5_badge_media": "マイスターとパチュケ氏 (1906)",
    "s6_m5_caption": "1906年9月の歴史的オリジナル写真：フェルト裁断作業台を囲むヴルツェン工場のマイスターとパチュケ社長",
    "s6_m6_badge": "現代 • レンナー提携",
    "s6_m6_title": "「ヴァイケルト・シュペツィアル」復刻とレンナー提携",
    "s6_m6_subtitle": "ヴルツェン伝統工場とレンナー・モイゼルヴィッツ本工場との緊密な隣接関係",
    "s6_m6_bullet_1": "<strong>2010年に伝統処方を復刻：</strong>ブラント家が1903年のオリジナル配合を再現し、最高峰の音響品質を復活。",
    "s6_m6_bullet_2": "<strong>至近距離（わずか65km）：</strong>ヴルツェンとレンナー・モイゼルヴィッツ工場は中部ドイツ伝統クラスター内で隣接。",
    "s6_m6_bullet_3": "<strong>職人同士の直接対話：</strong>わずか1時間の距離が、フェルト職人とハンマー技師の密接な現地共同調音を実現。",
    "s6_m6_fact": "📍 わずか65km：ヴルツェン ↔ レンナー・モイゼルヴィッツの直接提携",
    "s6_m6_caption": "ヴルツェン製ヴァイケルト・シュペツィアル：究極の整音性と豊かな響き",
