    "s6_c1_desc": "化学添加物を一切使わない純機械的縮絨 — 俊敏な反発力と澄んだコンサート音色を実現",
    "s6_tab6_year": "現在",
    "s6_m6_year": "現在",
    "s6_notes": "スライド 6: ヴルツェンフェルト工場（FFW）のヴルツェンにおける1783年創業からの歴史と、ヴァイケルト・フェルトの音響的秘密。全6つの歴史的節目を紹介：1783年ヴルツェン創業、1847年ドイツ初のピアノフェルト開発（革巻きからの転換）、1850〜67年万博金メダル、1861年ミュールグラーベン大工場での蒸気機械化と軟水活用、1906年年間20万台分の世界首位供給、そして現代のルイス・レンナー専用「ヴァイケルト・シュペツィアル」復刻。特にヴルツェン工場とレンナー・モイゼルヴィッツ本工場との極近距離（わずか約65km）を強調してください。職人同士の直接対話、最短の輸送経路、完璧な品質調整を可能にしています。",
    "s7_category": "第2部：フェルト製造 • 原毛選定＆秘伝ブレンド",
    "s7_title": "純粋メリノウールと繊維ブレンドの秘伝",
    "s7_subtitle": "無圧縮で届く海外産原毛と緻密な繊維配合がハンマーフェルトの弾性を決定づける",
    "s7_r1_step": "工程 01",
    "s7_b1_badge": "原毛セレクション",
    "s7_c1_title": "無圧縮の海外産メリノウールと無傷の繊維スケール構造",
    "s7_bullet_1": "<strong>無圧縮ベール輸送：</strong> 緩やかに梱包して輸送することで、微細なケラチンスケール（鱗片）と繊維弾性を完全に保護。",
    "s7_bullet_2": "<strong>強い天然クリンプ（縮れ）：</strong> 無数の天然スプリング構造が縮絨時の深い絡み合いと俊敏な復元力を生み出す。",
    "s7_bullet_3": "<strong>天然ラノリン保持：</strong> 穏やかな洗浄で天然羊毛脂を残し、繊維のしなやかさと耐経年性を維持。",
    "s7_macro_tag": "繊維マクロ",
    "s7_b2_badge": "無圧縮メリノ原毛",
    "s7_caption_1": "強い天然クリンプを保った無圧縮メリノ原毛",
    "s7_r2_step": "工程 02",
    "s7_b3_badge": "繊維ブレンド処方",
    "s7_c2_title": "繊細な開繊工程と緻密な繊維ブレンド処方",
    "s7_m_bullet_1": "<strong>緻密な繊維配合：</strong> クラウンの張力を担う長繊維と、内部密度を高める細繊維を精密に配合。",
    "s7_m_bullet_2": "<strong>多段階の空気開繊：</strong> 優しい開繊と空気流撹拌により、繊維束を傷めず一本ずつ均一にほぐす。",
    "s7_m_bullet_3": "<strong>調湿コンディショニング：</strong> カード工程前の均一な調湿が静電気・繊維折れ・密度ムラを防止。",
    "s7_b4_badge": "FFW 混合チャンバー",
    "s7_caption_2": "ヴルツェン工場における羊毛ロットの空気開繊・ブレンド工程",
    "s7_notes": "スライド 7: FFWヴルツェンにおける最初の2工程を統合解説：1. 無圧縮輸送で天然クリンプとラノリンを保ったメリノ原毛、2. 長繊維と細繊維を空気開繊チャンバーで均一に配合する秘伝のブレンド工程。",
    "s8_category": "第2部：フェルト製造 • カーディングと繊維配向",
    "s8_title": "カーディング（梳毛）：平行配向による繊細なフリース形成",
    "s8_subtitle": "均一な弾性と予測可能なニードリング整音を支える精密な繊維配向",
    "s8_bullet_1": "<strong>カーディング（梳毛）：</strong> 微細な針布ローラーが開繊された羊毛を丁寧に梳き、繊維を平行に整列させます。",
    "s8_bullet_2": "<strong>明確な繊維方向：</strong> 形成された極薄のフリースウェブは、設計通りの正確な主配向を備えます。",
    "s8_bullet_3": "<strong>計画的な積層：</strong> 複数のフリース層を重ね合わせ、所定の板厚・引張強度・テーパー構造を形成します。",
    "s8_bullet_4": "<strong>整音の前提条件：</strong> 平行に整列した繊維のみが、後の針刺し整音で切断されず均一に押し分けられます。",
    "s8_caption_1": "明確な繊維方向を持つ均一なフリース帯へと梳き上げられるメリノウール",
