    "s8_b2_badge": "カーディング＆フリース",
    "s8_panel_title": "ドラムカード機による繊維の平行配向",
    "s8_panel_subtitle": "打弦時の反発挙動を完全に制御する縦横配向設計",
    "s8_fact_badge": "🧵 繊維の平行配向が精密整音の絶対的土台",
    "s8_spotlight_badge": "フリース構造",
    "s8_spotlight_title": "整音のための必須条件",
    "s8_spotlight_desc": "平行に並んだ繊維のみが整音針の深刺しに予測通り均一に応答",
    "s8_texture_tag": "フリースウェブ：整列繊維",
