    "s8_hl1_desc": "整音針が繊維を断ち切ることなく滑らかに押し分ける。",
    "s8_hl2_title": "滑らかな密度勾配：",
    "s8_hl2_desc": "交差積層構造により、強打時でも層間剥離を徹底防止。",
    "s8_hl3_title": "繊維長の最大保持：",
    "s8_hl3_desc": "丁寧なカード処理で繊維の破断を防ぎ、フリースの優れた引裂強度を確保。",
    "s8_b3_badge": "フリース配向構造",
    "s8_c1_title": "整音作業を支える不可欠な前提条件",
    "s8_c1_desc": "平行に整流された繊維構造のみが、整音針の刺入に対して予測可能かつ均一に反応します",
    "s8_notes": "スライド 8：カーディング工程ではドラムカード機が開繊羊毛を平行に梳き、極薄のフリースを形成します。ここで明確な繊維方向が作られるからこそ、後の整音で繊維に直交する正確な針刺しが可能になる点を強調してください。",
    "s9_category": "第2部：フェルト製造 • 縮絨（フェルティング）工程",
    "s9_title": "縮絨の4大要素：蒸気・圧力・振動運動・熟練の経験",
    "s9_subtitle": "ムルデ川の軟水を用いた純機械・熱的繊維結束 — 接着剤・合成樹脂100%不使用",
    "s9_bullet_1": "<strong>1. 熱蒸気：</strong>キューティクルを開きケラチンを柔軟化。",
    "s9_bullet_2": "<strong>2. 機械圧力：</strong>フリース層を均一に圧着し高密度化を促進。",
    "s9_bullet_3": "<strong>3. 振動摩擦：</strong>繊維の微細なキューティクルを立体的に深層結束。",
    "s9_bullet_4": "<strong>4. 熟練の技：</strong>理想の縮絨タイミングを見極め、極上の弾性と音色を実現。",
    "s9_c1_title": "1. 熱蒸気",
    "s9_c2_title": "2. 機械的圧力",
