    "s9_c4_desc": "縮絨を止める最適瞬間を見極める熟練の感覚が、自己弾性と倍音の豊かさを決定します。",
    "s9_caption_1": "蒸気・圧力・振動のもとで積層フリースを均質なフェルト原反へと鍛え上げる縮絨工程",
