    "s9_b6_badge": "熟練の技",
    "s9_notes": "スライド 9：ヴルツェンにおける縮絨の4要素（熱蒸気・機械圧力・振動運動・熟練の経験）を解説します。合成樹脂や接着剤を一切使わず、ムルデ川の軟水と熱・機械運動のみでケラチン鱗片を強固かつ弾力的に結束させる点が核心です。",
    "s10_category": "第2部：フェルト製造 • 最大縮絨密度と自己弾性",
    "s10_title": "縮絨密度 56%（0.56 g/cm³）：純機械的縮絨の物理的限界",
