    "s10_hl3_desc": "何万回もの打鍵に対しても均一な密度を維持。",
    "s10_panel_title": "物理的限界点における究極の圧縮度",
    "s10_panel_subtitle": "繊維が理想的に密着する最適点まで精緻に縮絨圧縮",
    "s10_bullet_1": "<strong>最大繊維圧縮：</strong>繊維を損傷することなく純粋な機械的手段で到達できる限界圧縮。",
    "s10_bullet_2": "<strong>最高の天然反発弾性：</strong>コンサートグランドの打弦に求められる自己弾性の物理的最適値。",
    "s10_bullet_3": "<strong>合成樹脂フリー：</strong>人工硬化剤や化学薬品に頼らないため、恒久的な響きの豊かさを保証。",
    "s10_b3_badge": "究極の音響性能",
    "s10_notes": "スライド 10：純粋な機械縮絨の物理的限界である「縮絨密度 56%（0.56 g/cm³）」を解説します。これ以上は繊維を潰すか化学硬化剤に頼るしかなく、56%こそが繊維の弾力性と豊かな音色を損なわない最高到達点です。",
