    "s11_bullet_2": "<strong>完全無研磨プロセス：</strong> ヴァイケルト製法は表面研磨を一切行わず、張力繊維を1本も断ち切りません。",
    "s11_bullet_3": "<strong>滑らかな曲げ半径：</strong> ウッドコア周囲へ強く曲げても表層は滑らかで割れやズレが生じません。",
