    "s12_bullet_1": "<strong>楔形プロファイル：</strong> 低音部は厚く、高音部へ向けて徐々に薄く高密度に縮絨。",
    "s12_bullet_2": "<strong>豊富なラインナップ：</strong> コンサート用からブランド別OEM、歴史的楽器の修復用まで30種以上の配合を常備。",
    "s12_bullet_3": "<strong>空調管理と熟成休止：</strong> 厳密な湿度制御・防虫監視と規定の休止期間により縮絨時の残留応力を解消。",
    "s12_b2_badge": "フェルト原反保管庫",
