    "s12_notes": "スライド 12: モイゼルヴィッツ製造ラインの冒頭として、30種以上の空調熟成トップフェルト原反と、標準6色＋特注対応のアンダーフェルト体系を一望します。",
    "s13_category": "第3部：ハンマーヘッド製造 • ヴァイケルト・スペシャル＆電子顕微鏡解析",
    "s13_title": "「ヴァイケルト・スペシャル」— レンナー専用配合",
    "s13_subtitle": "1903年ヴルツェン伝統処方による最大縮絨密度56%と高残留羊毛脂（ラノリン）含有率",
    "s13_kpi": "縮絨密度 56%",
    "s13_b1_badge": "FFW × STFI 試験解析",
    "s13_c1_title": "最高水準の縮絨密度と保護されたケラチン繊維",
    "s13_c1_desc": "穏やかな原毛洗浄と高密度縮絨により、最大密度56%と高い残留羊毛脂を両立（STFI試験報告書 P2024 0903）。",
    "s13_m1_val": "56%",
    "s13_m1_lbl": "最大縮絨密度",
    "s13_m1_sub": "硬化剤不使用 0.56 g/cm³",
    "s13_m2_val": "0.36%",
    "s13_m2_lbl": "残留油脂率 (ISO 3074)",
    "s13_m2_sub": "比較試料(0.26%)比 +38%",
    "s13_m3_val": "−65%",
    "s13_m3_lbl": "温湿度サイクル膨潤",
    "s13_m3_sub": "13.69% → わずか 4.81%",
    "s13_bullet_1": "<strong>縮絨密度 56%：</strong> 化学硬化剤を使わず純機械縮絨のみで到達する最高密度（0.56 g/cm³）が強い内部張力を形成。",
    "s13_bullet_2": "<strong>残留油脂率 0.36%（ISO 3074）：</strong> 穏やかな洗浄により天然羊毛脂を38%多く保持（比較試料0.26%）し湿気を防ぐ。",
    "s13_bullet_3": "<strong>実証された耐湿安定性：</strong> STFI 48時間温湿度サイクル試験で厚み膨潤を65%抑制（13.69%に対しわずか4.81%）。",
    "s13_bullet_4": "<strong>健全な鱗状表皮と整音保持：</strong> SEMで確認できるエピキューティクルが高い繊維牽引力と長期にわたる音色安定性を保証。",
    "s13_fact": "🔬 根拠：STFI公認試験報告書 P2024 0903（M. Kermer、ISO 3074・耐湿サイクル試験）",
    "s13_rem_btn_1x": "1× 全体像 (1 mm)",
    "s13_rem_btn_10x": "10× 繊維拡大 (100 µm)",
    "s13_rem_btn_22x": "22× 鱗片ズーム",
    "s13_rem_btn_loupe": "🔍 ライブルーペ",
    "s13_rem_btn_macro": "トップフェルト帯 W 1512 K",
    "s13_rem_reticle": "10× 拡大視野枠 (414 µm)",
    "s13_rem_scale_callout": "羊毛繊維のキューティクル鱗片",
    "s13_b2_badge": "STFI • SEM",
    "s13_caption_1": "SEM全体像 (STFI Mik59_24 • 1 mm)：最大縮絨密度56%を誇る高密度3次元メリノ繊維ネットワーク。",
    "s13_notes": "スライド 13: ヴァイケルト・スペシャルは純機械縮絨による最高縮絨密度56%を達成します。STFI公認試験報告書 P2024 0903（M. Kermer、2024年6月）により、残留油脂率は0.36%（比較試料0.26%に対し+38%、ISO 3074）と高く、48時間温湿度サイクル試験での厚み膨潤が65%低減（13.69%→4.81%）することが実証されています。右側のインタラクティブSEMビューアで1 mm全体像から100 µm単繊維・鱗状表皮まで拡大できます。",
    "s14_category": "第3部：ハンマーヘッド製造 • フェルト前加工",
    "s14_title": "フェルト前加工：トップフェルト裁断＆アンダーフェルト切削",
    "s14_subtitle": "公差1 mmのロボット自動帯裁断とプレス前の精密プロファイル加工",
    "s14_kpi_1": "公差 ≤ 1 mm",
    "s14_b1_badge": "01 • 6軸ロボット",
    "s14_c1_title": "ロボットによるトップフェルト裁断",
    "s14_bullet_1": "<strong>公差1 mmの帯裁断：</strong> 6軸ロボットが熟成済みテーパー原反を全幅にわたり歪みなく分割。",
    "s14_bullet_2": "<strong>無圧縮コールドカット：</strong> 鋭利な専用刃が熱変性や繊維潰れを起こさず平滑に切断。",
    "s14_bullet_3": "<strong>インラインロット印字：</strong> 裁断と同時に原反・製造番号を記録し完全な履歴管理を実現。",
    "s14_b2_badge": "トップフェルト • 6軸裁断",
    "s14_caption_1": "歪みなくトップフェルト帯を自動裁断する6軸ロボット",
    "s14_kpi_2": "公差 ±0.1 mm",
    "s14_b3_badge": "02 • 専用フライス加工",
    "s14_c2_title": "アンダーフェルトのプロファイル切削",
    "s14_bullet_4": "<strong>弾性カップリング層：</strong> 成形加工されたアンダーフェルトが木芯の打弦エネルギーを外層へ的確に伝達。",
    "s14_bullet_5": "<strong>薄く削り出した裾部（±0.1 mm）：</strong>±0.1 mmの公差で精密に切削された先端により、高音域まで継ぎ目のないハンマー輪郭を実現します。",
    "s14_bullet_6": "<strong>均一な型締め圧力：</strong> 計算された楔形断面がプレス圧を左右のフランクへ対称に配分。",
    "s14_b4_badge": "アンダーフェルト • 切削工程",
    "s14_caption_2": "接着プレスへセットする前にアンダーフェルト帯をプロファイル切削",
    "s14_notes": "スライド 14: フェルト前加工の2工程を統合紹介。上段は6軸ロボットによる公差1 mmの歪みないトップフェルト帯裁断とロット印字、下段は木芯と外層を結び均一なプレス圧を生むアンダーフェルトのプロファイル切削です。",
    "s15_category": "第3部：ハンマーヘッド製造 • ウッドコア（樹種＆形状）",
    "s15_title": "ハンマーウッドコア（木芯）：樹種・特性・プロファイル形状",
    "s15_subtitle": "高比重ハードウッド（シデ・メイプル）や油分豊富なコティベから、極細年輪で軽量なアメリカンウォルナットまで",
    "s15_b1_badge": "ハードウッド • 理想材",
    "s15_c1_title": "シデ材 (Hornbeam)",
    "s15_c1_desc": "乾燥工程は極めて繊細ですが、適切に乾燥させれば理想的で均質な木芯材となります。",
    "s15_b2_badge": "ハードウッド • 高弾性",
