    "s15_b7_badge": "断面設計図",
    "s15_caption_1": "レンナー製ウッドコア断面図：Form A・Form B・Form US・Form CSB",
    "s15_b8_badge": "厳選コア材在庫",
    "s15_caption_2": "厳選されたウッドコア材 — 無節・通直木理・精密乾燥済み",
    "s15_d1": "高比重 • 高安定",
    "s15_d2": "高比重 • 厳選材",
    "s15_d3": "超軽量 • 極細年輪",
    "s15_d4": "高比重 • 特定用途",
    "s15_notes": "スライド 15：レンナーの4種の木芯材。シデとメイプルは高比重のハードウッド（シデは乾燥が極めて難しいものの適切に乾燥させれば理想的。メイプルは弾性に富む反面、不規則な糖分沈着による個体差リスクがある）。油分を多く含むコティベも重く特定用途向け。最高級材は緻密な年輪と長繊維を持つ超軽量のアメリカンウォルナットで、輝かしい高音域（ディスカント）に最適。下段は対称形状（Form B, US, CSB）と非対称形状（Form A）。",
    "s16_category": "第3部：ハンマーヘッド製造 • 音響的質量バランス設計",
    "s16_title": "弦の重量に対する最適なハンマーヘッド重量の設計",
    "s16_subtitle": "低音約15 gから移行部の−1 g段差を経て最高音5 gへ：接触時間と弦振幅の最適バランス",
    "s16_tab_all": "🎹 全音域 (15→5 g)",
