    "s16_tab_treble": "③ 高音域 (5 gへ)",
    "s16_btn_strike": "打弦テスト",
    "s16_b1_badge": "打弦の物理",
    "s16_phys_title": "クラウンでの均衡：接触時間 τc ↔ 弦の振幅",
    "s16_phys_hint": "A₀–C₈を選択可能",
    "s16_b2_badge": "基本バランス原理",
    "s16_ratio_tag": "弦重量 ↔ ハンマー質量",
    "s16_principle_txt": "<strong>弦重量</strong>と<strong>ハンマー重量</strong>が適合するとき、<strong>接触時間 τc</strong>と<strong>弦の振幅</strong>が理想的な均衡に達します。",
    "s16_ctrl1_lbl": "1. 音域と3つの難所ゾーンを選択",
