    "s20_topic_5": "時間短縮",
    "s20_notes": "スライド 20: 核心となる技術革新を強調してください：5年間の研究開発から生まれた独自の測定・製造システムにより、理想的な音響スペクトルに合わせて精密に事前校正されています。その響きは新品のヤマハC1〜C3純正ハンマーをも凌駕し、整音作業は一切不要です。日常的に整音を行わない技術者にとっても失敗のリスクがありません。ネジ1本での取り付けと高張力ローラーにより、工房での3〜7日の重労働が現場でのわずか4〜5時間に短縮されます。搬出リスクがなく、部屋の響きに合わせた音色調整に十分な時間を割くことができます。",
