    "s26_exp_badge": "✦ 音響作用",
    "s26_notes": "スライド 26（第5部・整音導入）：最低音域 A₁（55 Hz、有効弦長 L = 1,560 mm）を例に、第1〜第12倍音（H₁〜H₁₂）の構築を実演します。まずフェルト硬度：針入れで柔らかくすると接触時間 τc（約3.8 ms）が伸びて高次倍音が dB 単位で減衰し、硬いクラウン（τc 約1.3 ms）では高次倍音が急増します。次にヤング＝ヘルムホルツの打弦点法則：1/8 L や 1/7 L では不協和な第7・第9倍音を節で抑えつつ、歌うような長3度 H₅（1/5 L）を豊かに保ちます。",
