    "s27_exp_badge": "✦ クリストフォリ (1700)",
    "s27_notes": "スライド 27：まず「1. クリストフォリの革巻きロール (1700)」で、中空ロールの表面張力が死荷重ゼロで高い復元力と短い接触時間 τc を生む原理を示します。次に「2. レンナー張力スプリング」へ切り替え、クラウン最高密度から最広部フランク½密度への勾配を解説します。4つの3段階スイッチで、クラウンや移行帯の過硬化は pp を妨げ、弾性不足やショルダー部の遮断は τc を延ばして ff を失わせることを実演します。",
