    "s28_exp_badge": "✦ 予備整音 • 青のFFウェッジ (9–10 / 2–3時)",
    "s28_notes": "スライド 28: 大原則として、常に巻かれた羊毛繊維の流れを基準にし、上部ゾーン（9:00〜3:00）では「繊維に対して直交（⊥・90°）」に針を押し入れて繊維を傷つけずに分けます。さらに重要な応用技法として「5. リベット上方 → フランク方向」を実演：リベット直上からフランクへ向けて『少数かつ深い針』を入れることで、下部の張力リザーブが活性化し、フェルト全体の弾力性と高次倍音（H7〜H12）が明確に向上します。",
    "s29_category": "第5部：整音 • 3本同音弦における幾何学的整合と位相",
