    "s29_kpi3_lbl": "同位相エネルギー",
    "s29_b2_badge": "✕ 不良1 • クラウンの傾き（片当たり）",
    "s29_notes": "ハンマークラウンと3本弦面の整合（スライド29）：整音針を入れる前の最重要工程です。クラウンの傾き、弦面の高さ不揃い、あるいは中凹みによってわずか0.2〜0.3 mmの接触差が生じると、3本の弦の発音タイミングに時間差 Δt が生まれます。中高次倍音ではこれが120°〜180°の位相差となり、波の山と谷が打ち消し合って合成波が減衰し、倍音スペクトルに深い欠落（コムフィルタ効果）を引き起こします。",
    "s30_category": "第5部：整音 • 弦の密着と整列",
    "s30_title": "弦の事前調整：ヒッチピン・駒ピン・アグラフの整列",
    "s30_subtitle": "「最高のハンマーヘッドも、楽器本体に整えられた響きしか引き出すことはできない！」",
    "s30_kpi": "4つの事前工程",
    "s30_b1_badge": "弦の密着・整列",
    "s30_c1_title": "最初の針入れに先立つ厳密な弦の密着と水平出し",
    "s30_c1_desc": "弦が確実に密着し、同一平面に揃い、純粋なユニゾンに整って初めてハンマー本来の音色を正しく診断できます。",
    "s30_bullet_1": "<strong>1. ヒッチピンと座面の清掃：</strong> 座面を清掃し、ヒッチピンでの弦の浮きや緩みがないか奥から順に点検します。",
    "s30_bullet_2": "<strong>2. 駒ピンへの密着：</strong> 真鍮ポンチと軽量ハンマーで弦を駒へ確実に密着させ、偽唸りや雑振動を解消します。",
    "s30_bullet_3": "<strong>3. アグラフ後方の水平・間隔調整：</strong> 精密プライヤーでアグラフ直後の3本弦の間隔と高さを同一平面に揃えます。",
    "s30_bullet_4": "<strong>4. ユニゾン・ダンパー最終確認：</strong> ハンマーとの同時接触、ダンパーの止音、完全無うなりのユニゾンを確認します。",
    "s30_fact": "🎵 鉄則：弦の密着不良や不揃いな弦面は、針入れでは決して解決できません！",
    "s30_b2_badge": "01 • ヒッチピン",
    "s30_b3_badge": "02 • 駒ピン密着",
    "s30_b4_badge": "03 • アグラフ整列",
    "s30_b5_badge": "04 • 止音・同音確認",
    "s30_caption_1": "プレート座面とヒッチピン周辺の清掃および密着点検",
    "s30_caption_2": "真鍮ポンチと軽量ハンマーで駒ピン部の弦を駒へ確実に密着",
    "s30_caption_3": "アグラフ直後で3本弦の間隔と高さを精密プライヤーで均一化",
    "s30_caption_4": "レンナーハンマー上の弦列・ダンパー密着・同時発音を最終確認",
    "s30_notes": "スライド30：整音（針入れ）に入る前に不可欠な4つの実技工程（ヤマハC3へのレンナーキット組込実例）を解説します。①ヒッチピン座面の清掃・点検、②真鍮ポンチによる駒ピンへの密着、③アグラフ後方での3本弦の間隔・水平調整、④ダンパー動作と純粋なユニゾン発音の確認。",
    "s31_category": "第5部：整音 • 仕上げ・ウナ・コルダ整音",
    "s31_title": "中間・仕上げ・シフトペダル（ウナ・コルダ）整音",
    "s31_subtitle": "半音階での均一化、クラウン最大2 mmの微細針刺し、左ペダル（ウナ・コルダ）の整音",
    "s31_kpi": "最大 2 mm • ウナ・コルダ",
    "s31_b1_badge": "仕上げ・ペダル整音",
    "s31_c1_title": "左ペダル（ウナ・コルダ）まで含めたコンサート仕上げ",
    "s31_c1_desc": "全88音を通常奏法でもシフトペダル踏み込み時でも、雑音のない滑らかな音色の連なりへと仕上げます。",
    "s31_bullet_1": "<strong>1. BDKシングル針：</strong> 人間工学BDKホルダー（43-0003269）の短針でピアノ領域を繊細に整えます。",
    "s31_bullet_2": "<strong>2. 中間整音（ショルダー部）：</strong> 専用当て木で支え、フォルテ・ピアノ領域の突出した硬さを均一化します。",
    "s31_bullet_3": "<strong>3. クラウン最大2 mm針刺し：</strong> チョップスティック（43-0003271）で弦溝の間のみ深さ2 mm以内で微調整！",
    "s31_bullet_4": "<strong>4. クラウンの微細研磨：</strong> 針入れで毛羽立った羊毛繊維を細目ヤスリ（#320–400）で滑らかに整えます。",
    "s31_bullet_5": "<strong>5. ウナ・コルダ整音：</strong> 左ペダルを踏んで当たり面のみ繊細に針を入れ、擦れ音防止にクラウン左端を微細に面取り。",
    "s31_fact": "🪡 クラウンと左端の繊細な仕上げが、ウナ・コルダでも絹のような輝きを生みます！",
    "s31_b2_badge": "01 • BDK短針ホルダー",
    "s31_b3_badge": "02 • ショルダー部整音",
    "s31_b4_badge": "03 • クラウン最大2 mm微細針",
    "s31_b5_badge": "04 • ファイリング＆左端面取り",
    "s31_caption_1": "BDK短針ホルダーによるクラウン周辺の繊細な針入れ",
    "s31_caption_2": "専用当て木で支えながら肩部（ピアノ・フォルテ域）を整音",
    "s31_caption_3": "チョップスティックで弦間から弦溝の間のみを最大2 mm以内で微調整",
    "s31_caption_4": "細目ヤスリ（#320–400）でのファイリング整形・ウナコルダ左端の微細面取り",
    "s31_notes": "スライド 31：仕上げ整音の全5工程を解説します。①BDK短針ホルダー、②ショルダー部の中間整音、③チョップスティックによる弦溝間のみ最大2 mmの微細針刺し、④細目ヤスリ（#320–400）でのファイリング（整形）、⑤シフト整音（ウナ・コルダ）およびクラウン左端の微細な面取り。",
    "s32_category": "第5部：整音 • 硬化処理・熱アイロン・微細仕上げと重量設計",
