    "s32_w_treble_btn": "高音域側：重量を減らす (−m ↓)",
    "s32_w_detail_title": "中音〜低音 → 重量を増やす (+m)：",
    "s32_w_detail_body": "ハンマー重量を増やすことで太い弦へ十分なエネルギーが伝わり、豊かな基音と力強い音の芯が高まります。",
    "s32_b2_badge": "02 • 熱アイロン平滑化",
    "s32_kpi_2": "上限 135 °C 厳守",
    "s32_caption_2": "サーモスタット制御の整音アイロンでフェルト外層を平滑化・緻密化",
    "s32_c2_title": "熱アイロンによる平滑化（最大 135 °C）",
    "s32_c2_desc": "加熱アイロンで毛羽立ちを抑えて外層を緻密化し、フェルト外周の張力を高めます。",
    "s32_bullet_3": "<strong>最大135 °C厳守：</strong> これ以上の高温は羊毛ケラチンと天然ラノリンを熱損傷させます。",
    "s32_bullet_4": "<strong>均一な操作：</strong> 内部のバネ弾性を保つため、輪郭に沿って素早く均一に動かします。",
    "s32_fact_2": "🌡️ 温度管理必須：135 °C以下で繊維の脆化と黄変を防止",
    "s32_b3_badge": "03 • クラウン超微細仕上げ",
    "s32_kpi_3": "≤ 15 µm • Braun Series 1",
    "s32_svg3_foil": "Braun Series 1",
    "s32_svg3_cut": "浮き毛のみをカット",
    "s32_caption_3": "15 µmマイクロ研磨材（左）またはブラウン シリーズ1 シェーバー（右）",
    "s32_c3_title": "クラウン超微細研磨（≤ 15 µm）とシェーバー仕上げ",
    "s32_c3_desc": "極限まで滑らかなクラウン表面が毛羽による減衰をなくし、薬品なしで打弦接触硬度を高めます。",
    "s32_bullet_5": "<strong>最大15 µm（15ミクロン）の研磨材：</strong> クラウンを鏡面状に整え、明確な打弦接点を作ります。",
    "s32_bullet_6": "<strong>市販シェーバー（Braun Series 1）：</strong> 網刃で浮き毛だけを刈り取り、フェルト厚を削りません。",
    "s32_fact_3": "✨ 最も安全な最適化：純粋な音色とバネ機能100%維持",
    "s32_notes": "スライド 32：ラッカー系硬化剤の部位別効果をインタラクティブに実演します。①リベット周辺ではハンマーの土台（基音）を強化し、塗料によってはフェルト張力も高めます。②ウッドコア上部への側面塗布は高次倍音を強めますが、量が多すぎるとフランクとの結合部が固着して複合バネ機能が損なわれます。③クラウン頂点への直塗りはガラス質で鼻にかかった硬さを生み、恒久的損傷を招くため避けます。④コア上部への塗布はすべて経時でさらに圧縮・硬化する点に注意が必要です。⑤基音の豊かさや音の抜けを高めるには、中音〜低音で重量を増やし（+m）、高音域へ向けて重量を減らします（-m）。右側に最大135 °Cの熱アイロンと、15 µm研磨材／Braun Series 1によるクラウン微細仕上げを併記しています。",
    "s33_category": "第5部：展望 • レンナー・アカデミー＆技術対話",
    "s33_title": "レンナー・アカデミー＆マイスター技術対話",
    "s33_subtitle": "実践的なマイスター講習会、モイゼルヴィッツ工場見学、世界中の技術者との直接対話",
    "s33_b1_badge": "実践マイスター講習",
    "s33_b2_badge": "モイゼルヴィッツ本社工場",
    "s33_b3_badge": "LOUIS RENNER GMBH",
    "s33_c1_title": "レンナー・アカデミー研修プログラム",
    "s33_c1_desc": "アクション幾何学、ハンマーヘッド取付、ヤマハキット組込、コンサート整音を網羅する実践ワークショップ。",
    "s33_bullet_1": "<strong>マイスターからマイスターへ：</strong> レンナー純正仕様と計測基準に基づく実践型セミナー。",
    "s33_c2_title": "工場見学＆ダイレクト技術サポート",
    "s33_c2_desc": "モイゼルヴィッツに集約された最新製造現場をご見学いただき、現場直結の技術サポートをご活用ください。",
    "s33_bullet_2": "<strong>マイスターとの直接対話：</strong> モイゼルヴィッツ工場訪問、特注ハンマー製作、個別技術相談に随時対応。",
    "s33_caption_1": "Louis Renner GmbH • Meuselwitz",
    "s33_caption_2": "1882年創業 — 至高のピアノ音色を共に創るパートナー",
    "s33_notes": "スライド 33：レンナー・アカデミー講習会およびモイゼルヴィッツ工場見学へご招待します。",
