    "s2_notes": "第 2 页：向现场嘉宾介绍德国路易·雷诺（Louis Renner）莫伊塞尔维茨总厂的两位核心联系人：负责公司整体战略与全球制造商合作的首席执行官 Erik Stieler，以及负责莫伊塞尔维茨总厂的工厂厂长 Clemens Kunert。提示：点击右上角“保持联系 • 扫码存名片”或直接点击二维码，可切换为适合会场后排扫码的大尺寸电子名片视图。",
