    "s3_c5_pill": "第 26–34 页",
    "s3_c1_title": "历史与莫伊塞尔维茨工厂",
    "s3_c2_title": "乌尔岑纯羊毛毡制造",
    "s3_c3_title": "弦槌精密制造",
    "s3_c4_title": "雅马哈定制套件（C1–C3）",
    "s3_c5_title": "专业整音与技术交流",
    "s3_c1_desc": "始于1882年逾140年的击弦机与弦槌传统，以及莫伊塞尔维茨全工序整合工厂的建设纪实与航拍巡礼。",
    "s3_c2_desc": "始于1783年的乌尔岑毛毡厂、高品质羊毛混纺配方、梳毛铺网、精准缩绒密度，以及不打磨毛毡板对结构与音色的关键影响。",
    "s3_c3_desc": "毛毡库、Weickert Special 电镜分析、裁切、槌芯木材与配重、压制与胶合、CNC 轮廓铣削与表面精密校准，以及铆接与钻孔。",
    "s3_c4_desc": "C1–C3 即装升级套件（现场 4–5 小时完工）、延时安装实录、钢琴家实测反馈与声学频谱对比（H₁–H₁₂ 至 C₈）。",
    "s3_c5_desc": "A₁泛音结构、复合弹簧、整音模型、槌冠与弦平面、精整音、浸漆与熨烫增硬，以及雷诺学院与现场答疑。",
    "s3_open_chapter": "打开章节",
    "s3_notes": "第 3 页：介绍全篇五大核心章节：1. 品牌历史与莫伊塞尔维茨总厂（第 4–5 页）；2. 乌尔岑毛毡制造工艺（第 6–11 页）；3. 弦槌精密生产（第 12–19 页）；4. 雷诺雅马哈套件 C1–C3 与频谱分析（第 20–25 页）；5. 音乐会整音艺术与现场问答（第 26–34 页）。每张卡片均可直接点击跳转。",
    "s4_category": "第一部分：引言与历史 • 企业发展年表",
    "s4_title": "逾140年匠心传承与精密制造（1882年至今）",
    "s4_subtitle": "从斯图加特手工工坊成长为钢琴击弦机与弦槌的全球标杆",
    "s4_frequency_load": "✦ 莫伊塞尔维茨 2026 • 正在同步时间轴...",
    "s4_notes": "第 4 页：140余年荣耀时光轴（共9个关键里程碑）。重点阐述里程碑 1（1882年：斯图加特匠心工坊创立 — 击弦机开启百年传奇之旅；与卡尔·罗尼施全铸铁铠装音板的历史呼应）、里程碑 2（1906年：开启声学核心部件弦槌自主生产 — 从1700年克里斯托弗里皮革包裹纸卷弦槌到1906年雷诺自产弦槌，日后定义了每一架施坦威三角钢琴的独特音色并确立全球工业标准；克里斯托弗里、1700年早期击弦机、早期手工车间与1906年专用压力模具全景图集）、里程碑 3（1911年：工业电化革命与三角钢琴击弦机 — 传承埃拉尔复奏结构现代演奏之基石；迈向雷诺首批三角击弦机自主生产；奥斯卡·雷诺推进专用精密机床、工序优化并以数百台独立电机单驱彻底替代传统总轴皮带；全谱系制造完美闭环；埃拉尔、1808年结构与工业电化车间全景图集）、里程碑 4（1944年空袭重生）、里程碑 5（1951/1952年：曼弗雷德·雷诺博士）、里程碑 6（1990年：柏林墙倒塌与雷诺生死存亡之战 — 收购蔡茨击弦机基地以抵御捷克厂商冲击，力挽日产逾40架钢琴的第一大客户舒密尔）、里程碑 7（2011年：盖特林根新厂落成与从蔡茨迁至莫伊塞尔维茨后的现代化核心制造基地；莫伊塞尔维茨6,800平米与盖特林根双基地格局；盖特林根新总部与鸟瞰莫伊塞尔维茨生产基地全景图集）、里程碑 8（2019年：施坦威集团收购与深切缅怀阿尔尼姆先生）以及里程碑 9（恪守传统 · 塑造未来：2025年10月启动的莫伊塞尔维茨全流程整合圆满收官，落成全新现代化中央过滤排风吸附系统，并向盖特灵根团队致以深切谢意）。",
    "s5_category": "第一部分：引言与历史 • 莫伊塞尔维茨工厂升级",
    "s5_title": "工程纪实：莫伊塞尔维茨一体化新工厂的诞生",
    "s5_subtitle": "按时间顺序的建设纪实影像（2025年11月 – 2026年9月）及车间内部航拍巡礼",
    "s5_drone_btn": "无人机航拍",
    "s5_wing_prev": "◀ 上一画面",
