    "s5_drone_badge": "莫伊塞尔维茨新工厂内部无人机航拍 (2026)",
    "s5_drone_title": "竣工投产的莫伊塞尔维茨新工厂 — 室内无人机全景航拍",
    "s5_replay_btn": "↺ 重播翻页纪实",
    "s5_drone_finale": "无人机航拍终章",
    "s5_prev_btn": "上一步",
    "s5_notes": "第 5 页：莫伊塞尔维茨工厂在不停产条件下完成的 14 阶段升级纪实（2025年11月–2026年9月）：行政区与门厅腾退（阶段1–2）、管网施工与联动杆产线建设（阶段3–4）、垂直升降智能立体库（阶段5）、12米高且风量达12万m³/h中央除尘塔的承重地基与70吨起重机吊装（阶段6–8）、弦槌制造车间迁入（阶段9）、全厂集尘管网、全年恒湿45–50%屋顶空调中枢及击弦机与弦槌全线整合竣工（阶段10–14），随后无缝切换至车间内部无人机航拍。",
    "s6_category": "第二部分：琴毡制造 • 历史与传统",
    "s6_title": "乌尔岑毛毡厂（FFW）– 顶级钢琴弦槌毛毡的诞生地",
    "s6_subtitle": "乌尔岑 1783 • 从1847年德国首创工业琴毡到雷诺专属“魏克特特级”深度合作",
    "s6_play_label": "播放时光之旅",
