    "s6_m1_badge": "乌尔岑起源 1783",
    "s6_m1_title": "乌尔岑毛毡制造厂创立",
    "s6_m1_subtitle": "全球历史最悠久的工业毛毡制造企业 — 扎根萨克森州穆尔德河谷",
    "s6_m1_bullet_1": "<strong>1783年创立：</strong>约翰·丹克戈特·魏克特在乌尔岑奠定萨克森羊毛与高级制毡工艺传统。",
    "s6_m1_bullet_2": "<strong>精细毛毡先驱：</strong>传统手工工坊迅速壮大为欧洲顶尖的高端工业技术与声学纯羊毛毡制造中心。",
    "s6_m1_bullet_3": "<strong>深耕钢琴声学：</strong>极早专注于为方兴未艾的现代钢琴研制高弹性专属击弦介质。",
    "s6_m1_fact": "🏛 位于乌尔岑的全球历史最悠久工业羊毛毡制造企业",
    "s6_m1_caption": "从手工梳理原毛纤网到高密度面毡原板",
    "s6_m2_badge": "发明 1847",
    "s6_m2_title": "德国首创高品质工业钢琴弦槌毛毡",
    "s6_m2_subtitle": "帕茨克与魏克特于1847年颠覆欧洲传统钢琴击弦工艺",
    "s6_m2_bullet_1": "<strong>毛毡取代皮革：</strong>1847年首次成功以均质高弹性纯羊毛毡彻底替代坚硬不均的传统皮革包裹。",
    "s6_m2_bullet_2": "<strong>技术与经营协同：</strong>魏克特的企业远见与帕茨克的制毡专长共同奠定国际声誉。",
    "s6_m2_bullet_3": "<strong>穆尔德河天然水质：</strong>穆尔德河矿物质极低的天然纯净软水，确保羊毛纤维得到最温和的纯净处理。",
    "s6_m2_fact": "🎹 行业里程碑：乌尔岑特级琴毡终结钢琴皮革击弦时代",
    "s6_m2_caption": "格尔策恩水磨坊旧址（1850年）：在穆尔德河中孤岛建立早期制毡工场",
    "s6_m3_badge": "世博金奖 1851",
    "s6_m3_title": "伦敦与巴黎世博会揽获世界金奖",
    "s6_m3_subtitle": "在莱比锡、伦敦与巴黎世博会上屡获最高金奖",
    "s6_m3_bullet_1": "<strong>揽获世博金奖：</strong>接连斩获莱比锡（1850）、伦敦（1851）与巴黎（1867）最高世博金奖，名满天下。",
    "s6_m3_bullet_2": "<strong>国王亲临视察：</strong>萨克森王国历代君主亲临视察乌尔岑制造工场，盛赞其卓绝工艺。",
    "s6_m3_bullet_3": "<strong>欧洲名厂一致之选：</strong>维也纳、巴黎与伦敦的顶级钢琴制造大师全线指定采用魏克特毛毡。",
    "s6_m3_fact": "🏅 1851伦敦、1867巴黎及1850莱比锡世博金牌",
    "s6_m3_caption": "因极致毛毡工艺与纯净度而荣获的历史世博会珍藏金牌",
    "s6_m4_badge": "扩张 1861",
    "s6_m4_title": "乌尔岑水渠沿岸工业化大规模扩产",
    "s6_m4_subtitle": "蒸汽动力、现代化高效缩绒机组与穆尔德纯净软水汇聚",
    "s6_m4_bullet_1": "<strong>规模化现代工厂：</strong>1861年在乌尔岑水渠旁落成自备蒸汽动力机房的现代化大跨度厂区。",
    "s6_m4_bullet_2": "<strong>高精缩绒机群：</strong>专属蒸汽动力大型缩绒设备确保毛毡具备绝佳的密度梯度与极其严苛的批次稳定性。",
    "s6_m4_bullet_3": "<strong>温和洗毛保护：</strong>极软天然活水完美呵护美利奴初剪羊毛表面的天然微观角质鳞片。",
    "s6_m4_fact": "⚙️ 乌尔岑水渠蒸汽动力缩绒与天然软水工场",
    "s6_m4_caption": "1871年乌尔岑钢琴毛毡工厂与水运河渠原始历史版画",
    "s6_m5_badge": "全球领军者 1906",
    "s6_m5_title": "年供20万架钢琴用毡的世界行业领袖",
    "s6_m5_subtitle": "帕茨克厂长、制毡大师团队与350名高级技师（1906年）",
    "s6_m5_bullet_1": "<strong>领跑全球市场：</strong>乌尔岑每年为全球多达20万架立式与三角钢琴供应高品质弦槌毛毡。",
    "s6_m5_bullet_2": "<strong>全球统一标杆：</strong>施坦威纽约总厂及欧洲各大顶级音乐会制造大师一致指定乌尔岑琴毡。",
    "s6_m5_bullet_3": "<strong>大师团队与帕茨克厂长：</strong>1906年历史原始档案照：与巨型梯级阶梯压制毛毡原板合影。",
    "s6_m5_fact": "🌎 确立施坦威纽约总厂及全球名琴统一参考标准",
    "s6_m5_badge_media": "制毡大师与帕茨克厂长 (1906)",
    "s6_m5_caption": "1906年9月历史原始照片：乌尔岑毛毡厂全体大师与帕茨克厂长在阶梯裁切台前合影",
    "s6_m6_badge": "当下 • 雷诺独家合作",
    "s6_m6_title": "“魏克特特级”（Weickert Spezial）重生与雷诺深度战略合作",
    "s6_m6_subtitle": "乌尔岑百年工场与雷诺莫伊塞尔维茨（Meuselwitz）总厂的黄金近邻优势",
    "s6_m6_bullet_1": "<strong>2010年重现经典配方：</strong>布兰德家族完整恢复1903年乌尔岑原厂配方，重现音乐会级声学品质。",
    "s6_m6_bullet_2": "<strong>近邻优势（仅相距65公里）：</strong>乌尔岑与雷诺莫伊塞尔维茨同处德国中部深厚钢琴制造核心产业腹地。",
    "s6_m6_bullet_3": "<strong>面对面大师协同：</strong>极短路程实现制毡大师与弦槌技师现场即时深度调校，精准定制最佳密度与弹性。",
    "s6_m6_fact": "📍 仅相距65公里：乌尔岑 ↔ 雷诺莫伊塞尔维茨直接深度共创",
    "s6_m6_caption": "乌尔岑魏克特特级毛毡：赋予弦槌极致整音张力与深邃共鸣",
    "s6_felt_badge": "100% 纯天然美利奴初剪羊毛",
    "s6_felt_title": "魏克特顶级纯羊毛毡的声音秘密",
    "s6_felt_subtitle": "不含任何化学添加剂的纯物理机械缩绒——赋予快速回弹与纯净通透的音乐会音色",
