    "s6_hl1_title": "独家精选三洲原毛拼配：",
    "s6_hl1_desc": "精选自阿根廷、南非与新西兰的长纤维与卷曲羊毛，构筑极高抗拉强度的毛毡基体。",
    "s6_hl2_title": "纯物理缩绒，无化学树脂：",
    "s6_hl2_desc": "仅依托穆尔德活水、温热与吨位重压，绝无阻碍振动、死板发硬的化学胶黏剂。",
    "s6_hl3_title": "毫秒级瞬时高弹回弹：",
    "s6_hl3_desc": "天然角蛋白分子微弹簧结构击弦后毫秒级闪电反弹离弦，完美释放华丽纯净的泛音列。",
