    "s6_c1_title": "魏克特毛毡的不传之秘",
    "s6_c1_desc": "不含任何化学添加剂的纯物理机械缩绒——赋予快速回弹与纯净通透的音乐会音色",
    "s6_tab6_year": "今日",
    "s6_m6_year": "今日",
    "s6_notes": "第 6 页：乌尔岑毛毡厂（FFW）自1783年创立于乌尔岑以来的传奇厂史与魏克特高级琴毡的声音奥秘。生动呈现六大历史里程碑：1783年在乌尔岑创立、1847年德国首创工业钢琴纯羊毛毡、1850-1867年世博金奖与国王盛赞、1861年水渠沿岸蒸汽机械化大工场与穆尔德纯净软水、1906年年供20万架钢琴的世界霸主地位，以及专为雷诺重生的“魏克特特级”。特别重点强调乌尔岑毛毡厂与雷诺莫伊塞尔维茨总厂极近的地理空间优势（相距仅约65公里）：实现制毡大师与弦槌大师零距离深度实时交流调校、零延时物流与极其严密的音色匹配。",
    "s7_category": "第二部分：毛毡制造 • 原毛甄选与秘制混毛配方",
    "s7_title": "纯正美利奴原毛与秘制纤维混配工艺",
    "s7_subtitle": "未压缩海外原毛与量身定制的纤维配比，奠定顶级弦槌毛毡的声学根基",
    "s7_r1_step": "工序 01",
    "s7_b1_badge": "原毛甄选",
    "s7_c1_title": "未压缩海外美利奴原毛与完整天然毛鳞结构",
    "s7_bullet_1": "<strong>未压缩松包运输：</strong> 松散打包远洋运输虽增加物流体积，但完整保护了微观角蛋白毛鳞结构。",
    "s7_bullet_2": "<strong>高卷曲天然弹性：</strong> 数百万微小天然螺旋弹簧在缩绒时紧密咬合，赋予极速回弹力。",
    "s7_bullet_3": "<strong>保留天然羊毛脂：</strong> 温和清洁保留适量天然羊毛脂（Lanolin），令纤维持久柔韧不脆化。",
    "s7_macro_tag": "纤维微距",
    "s7_b2_badge": "未压缩原毛",
    "s7_caption_1": "保持天然高卷曲弹性的未压缩美利奴原毛",
    "s7_r2_step": "工序 02",
    "s7_b3_badge": "纤维混配配方",
    "s7_c2_title": "温和开松解团与精密长短纤维混配配方",
    "s7_m_bullet_1": "<strong>精密混配比例：</strong> 均衡搭配承载槌冠拉力的长纤维与充实内部密度的细绒纤维。",
    "s7_m_bullet_2": "<strong>多级气动开松：</strong> 柔和拨散与气流悬浮混合，在不损伤毛鳞的前提下解开纤维团。",
    "s7_m_bullet_3": "<strong>恒湿调质处理：</strong> 梳理前均匀吸湿，彻底消除静电吸附、纤维断裂与局部硬结。",
    "s7_b4_badge": "FFW 气动混毛室",
    "s7_caption_2": "乌尔岑毛毡厂内的气动开松与多批次原毛混配室",
    "s7_notes": "第 7 页：整合乌尔岑毛毡厂前两道核心工序：1. 未压缩远洋运输保留高卷曲毛鳞与天然羊毛脂的美利奴原毛；2. 在气动开松混毛室中将抗拉长纤维与致密细绒按秘制比例均匀混配。",
    "s8_category": "第二部分：毛毡制造 • 梳毛与纤维走向",
    "s8_title": "梳毛工序：平行梳理形成均匀柔软纤网",
    "s8_subtitle": "定向纤维排布：奠定均匀回弹与精准针刺整音的物理基础",
    "s8_bullet_1": "<strong>精细梳理（Carding）：</strong> 精密针布滚筒轻柔梳理开松后的原毛，解开纠结并使纤维平行排列。",
    "s8_bullet_2": "<strong>明确纤维走向：</strong> 梳理出的薄如蝉翼的羊毛纤网具备严格受控的主导纤维方向。",
    "s8_bullet_3": "<strong>受控铺网叠层：</strong> 多层纤网有序铺叠，精准构建目标板厚、抗拉强度与锥形梯度。",
    "s8_bullet_4": "<strong>针刺整音前提：</strong> 唯有顺向排列的纤维才能在日后针刺整音时被平顺分拨，而非被割断。",
    "s8_caption_1": "将美利奴羊毛梳理成纤维走向明确的均匀连续纤网",
