    "s8_b2_badge": "梳理与絮片",
    "s8_panel_title": "梳毛机滚筒精准顺梳羊毛纤维",
    "s8_panel_subtitle": "精准控制纵向与横向排布，保障触键反弹高度可控",
    "s8_fact_badge": "🧵 纤维平行顺向排列是精准整音的根本基石",
    "s8_spotlight_badge": "薄绒网结构",
    "s8_spotlight_title": "大师级整音前提",
    "s8_spotlight_desc": "唯有顺直排列的羊毛纤维，方能让整音针获得恒定可控的触感反馈",
    "s8_texture_tag": "绒网结构：平行顺向毛丝",
