    "s8_hl1_desc": "整音针平滑推移纤维之间，避免斩断羊毛结构。",
    "s8_hl2_title": "平滑渐变密度：",
    "s8_hl2_desc": "十字复合交错叠网，防范极限力度强奏时的内部层裂。",
    "s8_hl3_title": "最大化纤维保留：",
    "s8_hl3_desc": "极其轻柔的顺梳工艺杜绝纤维断裂，赋予羊毛絮片极高的结构抗拉强度。",
    "s8_b3_badge": "定向纤网结构",
    "s8_c1_title": "高阶整音调音的先决条件",
    "s8_c1_desc": "唯有定向平行梳理的纤维，才能在整音调音穿刺时呈现出精准可预测的匀质声学响应",
    "s8_notes": "第 8 页：梳毛工序通过滚筒梳毛机将美利奴原毛平行顺梳成纤薄均匀的纤网。请重点强调其与整音实操的直接联系：正因为在此确立了清晰的纤维走向，技师日后才能垂直于纤维方向精准针刺而不损伤结构。",
    "s9_category": "第二部分：毛毡制造 • 物理缩绒工序",
    "s9_title": "物理缩绒四大要素：蒸汽、压力、往复运动与匠师经验",
    "s9_subtitle": "采用穆尔德河天然软水的纯物理热机械交织——100%不含胶水与化学树脂",
    "s9_bullet_1": "<strong>1. 高温蒸汽：</strong>充分打开毛鳞片微孔，软化角蛋白分子链。",
    "s9_bullet_2": "<strong>2. 机械压力：</strong>持续层层匀压，启动渐进致密缩合。",
    "s9_bullet_3": "<strong>3. 往复振动：</strong>多维微幅摩擦使毛鳞片不可逆地深层咬合交锁。",
    "s9_bullet_4": "<strong>4. 匠师掌控：</strong>精准把控终点毫秒时机，铸就绝佳回弹与通透共振。",
