    "s9_hl2_desc": "天然角蛋白弹簧毫秒级快速复原，不易疲劳老化。",
    "s9_hl3_title": "纯净泛音呈现：",
    "s9_hl3_desc": "天然低矿软水杜绝杂质结晶堵塞毛细孔隙。",
    "s9_b6_badge": "匠人工艺",
    "s9_notes": "第 9 页：阐述乌尔岑缩绒工艺的四大支柱：高温蒸汽、机械压力、往复摩擦运动与大师经验。核心在于零合成树脂与化学粘合剂——仅凭穆尔德河天然软水、热能与机械作用即可令角蛋白毛鳞实现持久高弹交锁。",
    "s10_category": "第二部分：毛毡制造 • 最高缩绒密度与天然自弹力",
    "s10_title": "56% 缩绒密度（0.56 g/cm³）：纯机械物理缩绒的天然极限",
    "s10_subtitle": "在不损伤羊毛纤维、零化学增硬的前提下实现最高天然回弹力",
    "s10_b1_badge": "物理缩绒极限",
    "s10_b2_badge": "FFW 乌尔岑",
    "s10_c1_title": "56% 纯物理最高缩绒密度",
    "s10_c1_desc": "在缩绒工序中，毛毡原板被纯物理压实至羊毛纤维无法进一步靠拢的天然临界点——最高缩绒密度达 56%（0.56 g/cm³）。",
    "s10_caption_1": "乌尔岑毛毡厂内完成物理缩绒的锥形弦槌毛毡原板",
    "s10_caption_2": "乌尔岑工坊内对纯机械缩绒毛毡原板进行精细后整",
    "s10_fact_badge": "🎯 最高 56% 缩绒密度（0.56 g/cm³）：零硬化剂的纯天然回弹力",
    "s10_spotlight_badge": "声学巅峰表现",
    "s10_spotlight_title": "以柔韧弹力取代僵硬脆性",
    "s10_spotlight_desc": "56% 天然缩绒密度兼顾极短触弦时间与细腻宽广的动态控制。",
    "s10_texture_tag": "天然缩绒上限：56% 缩绒密度（0.56 g/cm³）",
    "s10_hl1_title": "极速离弦回弹：",
    "s10_hl1_desc": "击弦后瞬间回弹释放琴弦，不吃音、不阻碍发声振动。",
    "s10_hl2_title": "色彩丰富饱满音色：",
    "s10_hl2_desc": "高音区亮而不燥，基音饱满且高次泛音层次分明。",
    "s10_hl3_title": "长效稳定敲击寿命：",
    "s10_hl3_desc": "历经数万次强奏依然保持一致均质密度。",
    "s10_panel_title": "物理极限下的终极密度平衡",
    "s10_panel_subtitle": "毛毡板精准缩绒至羊毛纤维最紧密咬合的最佳临界点",
    "s10_bullet_1": "<strong>最大机械压缩极限：</strong>在绝不损伤羊毛天然纤维结构的前提下，实现最紧密的纯物理咬合。",
    "s10_bullet_2": "<strong>最高天然回弹弹力：</strong>契合音乐会演奏三角琴击弦所需的最理想回弹动力学标准。",
    "s10_bullet_3": "<strong>绝无合成树脂：</strong>零化学增硬剂与胶水，彻底杜绝刺耳死硬杂音，保障声学生命力。",
    "s10_b3_badge": "声学极致追求",
    "s10_notes": "第 10 页：解析纯物理缩绒的天然极限——56% 缩绒密度（即 0.56 g/cm³ 体积密度）。在此临界点上，美利奴羊毛纤维达到最紧密的无损咬合；若强行超越则只能依赖化学浸渍硬化或过度压溃，反而牺牲回弹活力与温暖音色。",
    "s11_category": "第二部分：毛毡制造 • 后压实定型与层理结构",
