    "s13_category": "第三部分：弦槌制造 • Weickert Special 与电镜微观结构分析",
    "s13_title": "“Weickert Special”——雷诺专属配方",
    "s13_subtitle": "传承1903年乌尔岑配方：实现56%最高缩绒密度与更高天然残脂率",
    "s13_kpi": "56% 缩绒密度",
    "s13_b1_badge": "FFW × STFI 权威检测",
    "s13_c1_title": "最高缩绒密度与受保护的角蛋白纤维",
    "s13_c1_desc": "温和原毛洗净与高强度缩绒相结合，兼具56%最高密度与更高天然残脂率（STFI检测报告 P2024 0903）。",
    "s13_m1_val": "56%",
    "s13_m1_lbl": "最高缩绒密度",
    "s13_m1_sub": "0.56 g/cm³ 纯物理缩绒",
    "s13_m2_val": "0.36%",
    "s13_m2_lbl": "残脂率 (ISO 3074)",
    "s13_m2_sub": "较0.26%对照样高 +38%",
    "s13_m3_val": "−65%",
    "s13_m3_lbl": "交变湿热膨胀率",
    "s13_m3_sub": "仅4.81%（对照13.69%）",
    "s13_bullet_1": "<strong>56% 最高缩绒密度：</strong> 纯机械缩绒达成的极限密度（0.56 g/cm³），零化学硬化剂即可建立强劲内张力。",
    "s13_bullet_2": "<strong>0.36% 天然残脂率（ISO 3074）：</strong> 温和洗毛多保留 38% 天然羊毛脂（对照样 0.26%），形成内部防潮屏障。",
    "s13_bullet_3": "<strong>权威验证气候稳定性：</strong> 在STFI 48小时交变湿热测试中，厚度膨胀率降低65%（仅4.81%，对照样达13.69%）。",
    "s13_bullet_4": "<strong>完整鳞片层与整音保持：</strong> 电镜下清晰可见的表皮鳞片赋予强劲纤维牵引力，确保音色经年持久稳定。",
    "s13_fact": "🔬 权威依据：STFI认证检测报告 P2024 0903（M. Kermer，ISO 3074 与交变气候测试）",
    "s13_rem_btn_1x": "1× 全景 (1 mm)",
    "s13_rem_btn_10x": "10× 纤维细节 (100 µm)",
    "s13_rem_btn_22x": "22× 鳞片深层放大",
    "s13_rem_btn_loupe": "🔍 实时放大镜",
    "s13_rem_btn_macro": "面毡条 W 1512 K",
    "s13_rem_reticle": "10× 细节视野框 (414 µm)",
    "s13_rem_scale_callout": "羊毛纤维表皮鳞片层",
    "s13_b2_badge": "STFI • 电镜",
    "s13_caption_1": "电镜全景 (STFI Mik59_24 • 1 mm)：高达 56% 最大缩绒密度的三维紧密交织美利奴羊毛网络。",
    "s13_notes": "第 13 页：Weickert Special 实现了高达 56% 的纯物理最高缩绒密度。根据 STFI 权威检测报告 P2024 0903（M. Kermer，2024年6月），温和洗毛保留了更高的天然残脂率（0.36% 对比 0.26%，提高 38%，ISO 3074），使 48 小时交变湿热测试中的厚度膨胀率大幅降低 65%（仅 4.81%，对照样达 13.69%）。可通过右侧交互式电镜缩放器从 1 mm 纤维网络无级放大至 100 µm 单根纤维及表皮鳞片。",
    "s14_category": "第三部分：弦槌制造 • 毛毡预处理",
