    "s14_subtitle": "1 mm 公差机器人自动分切与入模压制前的精密轮廓铣削",
    "s14_kpi_1": "公差 ≤ 1 mm",
    "s14_b1_badge": "01 • 六轴机器人",
    "s14_c1_title": "机器人面毡条分切",
    "s14_bullet_1": "<strong>1 mm 精密分条：</strong> 六轴机器人将熟成锥形毛毡板在全宽范围内无变形等宽分切。",
    "s14_bullet_2": "<strong>无挤压冷切：</strong> 锋利刀片平滑分离美利奴羊毛纤维，绝无热损伤或边缘压溃。",
    "s14_bullet_3": "<strong>在线批次赋码：</strong> 每条面毡同步标记原板号与订单号，实现全流程可追溯。",
    "s14_b2_badge": "面毡 • 六轴裁切",
    "s14_caption_1": "六轴机器人无变形分切面毡条实拍",
    "s14_kpi_2": "公差 ±0.1 mm",
    "s14_b3_badge": "02 • 轮廓铣削",
    "s14_c2_title": "底毡轮廓铣削",
    "s14_bullet_4": "<strong>弹性耦合桥梁：</strong> 轮廓铣削底毡将击弦冲量由坚硬实木槌芯平顺传导至外层面毡。",
    "s14_bullet_5": "<strong>精密削薄尾部（±0.1 mm）：</strong>以 ±0.1 mm 公差精密铣削收薄的两端确保直至高音区都能形成无缝闭合的榔头轮廓。",
    "s14_bullet_6": "<strong>对称锁模压力：</strong> 精准匹配的楔形截面将压模闭合力均匀分配至两侧槌翼。",
    "s14_b4_badge": "底毡 • 轮廓铣削",
    "s14_caption_2": "入模胶合前对底毡条进行精密轮廓铣削",
    "s14_notes": "第 14 页：集中展示毛毡预处理两大工序：上方六轴机器人以 1 mm 公差无变形分切面毡条并在线赋码；下方对底毡条进行楔形轮廓铣削，构建实木槌芯与面毡间的理想弹性过渡并均衡锁模压力。",
