    "s15_caption_1": "雷诺槌芯标准工程截面：Form A、Form B、Form US 与 Form CSB",
    "s15_b8_badge": "精选木坯库",
    "s15_caption_2": "严选榔头木芯条——无节疤、顺直纹理、精密控湿干燥",
    "s15_d1": "偏重 • 极稳定",
    "s15_d2": "偏重 • 需严选",
    "s15_d3": "极轻量 • 细密年轮",
    "s15_d4": "偏重 • 特定应用",
    "s15_notes": "第 15 页：雷诺四种木芯木材对比：鹅耳枥与枫木同属偏重硬木——鹅耳枥干燥工艺极为苛刻，但干燥得当后是最理想的木芯材；枫木弹性更佳，但因不规则糖分沉积更易产生偏差。雷诺选用的科蒂贝木因天然含油量高同样偏重，仅用于特定用途。最高等级的木材是年轮极其细密、长纤维且极轻的美国黑胡桃木，是塑造辉煌高音区的理想之选。下方为对称截面（B、US、CSB）与非对称截面（Form A）。",
    "s16_category": "第三部分：弦槌制造 • 声学质量配比设计",
    "s16_title": "弦槌最佳重量与琴弦重量的动态平衡",
    "s16_subtitle": "从低音约 15 g 经 −1 g 过渡阶跃至高音 5 g：接触时间与琴弦振幅的最佳平衡",
