    "s16_principle_txt": "当<strong>琴弦重量</strong>与<strong>弦槌重量</strong>精准匹配时，<strong>接触时间 τc</strong>与<strong>琴弦振幅</strong>达到理想动态平衡。",
    "s16_ctrl1_lbl": "1. 音区与三大关键过渡难点",
