    "s20_notes": "第 20 页：重点阐述核心技术突破：历经五年研发的专有测量与制造系统，使雷诺弦槌出厂即精准标定于目标声学频谱，在全新或现役雅马哈 C1–C3 上无需预整音即可呈现温暖饱满的音乐会音色。配合单螺丝原位安装、天然皮骨胶刚性粘接与高张力皮滚，将原本需 3–7 天的工坊大修缩短为现场 4–5 小时的高可靠交付。",
