    "s21_bullet_2": "<strong>即插即用安装：</strong> 将预校准轴架与槌柄直接旋入雅马哈原厂铝合金总档。",
    "s21_bullet_3": "<strong>现场精密整调：</strong> 直接在琴上完成对弦、击弦距离、脱进与档托的精准调校。",
    "s21_bullet_4": "<strong>零搬运风险：</strong> 三角琴无需运回工坊，直接结合现场空间声学完成最终匹配。",
    "s21_kpi": "1 个工作日",
    "s21_c1_title": "在钢琴安放现场一天内完成全套换装",
    "s21_c1_desc": "印度现场纪实（10:00–18:00）：当日原地完成拆旧、换装、整调、调律与音乐家试奏全流程。",
    "s21_fact": "⏱ 10:00–18:00：从拆卸旧槌到音乐会级交付，当日现场一步到位",
    "s21_notes": "第 21 页：展示印度现场全天安装延时摄影（10:00 至 18:00）。仅用 1 个现场工作日即完成雅马哈三角钢琴全套雷诺套件的换装、精密整调与调律交付。",
    "s22_category": "第四部分：雅马哈套件 • 印度现场安装实证 (2/2)",
