    "s22_m1_unit": "出厂即享音乐会音色",
    "s22_bullet_1": "<strong>如歌音乐会音色：</strong> 从生硬敲击感立即蜕变为温暖醇厚、富有穿透力的共鸣。",
    "s22_bullet_2": "<strong>通透高音与清晰低音：</strong> 旋律音区如钟鸣般延展，低音和弦层次清晰分明。",
    "s22_bullet_3": "<strong>细腻动态层次：</strong> 从极弱音（pp）到极强音（ff）皆可自如塑造丰富音色变化。",
    "s22_bullet_4": "<strong>轻盈敏捷复奏：</strong> 得益于精准标定的弦槌质量，触键回弹与连奏更加灵敏。",
