    "s25_notes": "第 25 页左侧汇总了 Louis Renner 雅马哈套件的四大实测声学优势（歌唱区 +2.53 dB / +79%、高音辉煌感 +1.87 dB / +54%、低音清晰度去浑 −3.28 dB，以及斜率平缓 +0.93 dB/kHz 与波峰提升 +0.42 dB）。右侧展示全动态范围（pp–ff）频谱斜率散点回归图与上限至钢琴最高音 C8（4,186 Hz / 最大 4,300 Hz）的实时计算器。",
