    "s26_exp_badge": "✦ 声学效应",
    "s26_notes": "第 26 页（第五部分整音开篇）：以低音 A₁（55 Hz，有效弦长 L = 1,560 mm）为例，交互演示钢琴音色由 H₁–H₁₂ 泛音构成的物理本质。首先演示弦槌软硬度：针刺柔化延长接触时间 τc（约 3.8 ms），以分贝（dB）为单位衰减高次泛音；高密硬槌（τc 约 1.3 ms）则大幅拉升高频泛音。随后演示杨-亥姆霍兹击弦点定律：在 1/8 L 或 1/7 L 处击弦可在波节处精准抑制不协和的 H₇（自然七度）与 H₉（大二度），同时保留决定歌唱色彩的大三度 H₅（1/5 L）。",
