    "s27_notes": "第 27 页：先从“1. 克里斯托弗里皮包纸卷 (1700)”切入：鹿皮包裹的中空羊皮纸圆筒利用圆周表面张力，零内部死重即可产生高回弹力与极短接触时间 τc。随后切换至“2. 雷诺复合张力弹簧弦槌”：槌冠压实度最高，至最宽侧翼递减为一半（½），并由胶水与铆钉锚固于木芯。通过四组三档开关直观演示：槌冠或槌肩过硬会丧失 pp，而弹性不足或槌肩锁死侧翼则会拉长 τc、导致无法奏出通透的 ff。",
