    "s28_notes": "第 28 页：首先强调核心准则：针刺整音时始终以毛毡纤维走向为基准，在上部扇区（9:00–3:00）保持垂直于纤维（⊥，90°）平稳压入，分拨而非切断纤维。除蓝、绿、橙、紫四区与 12 点槌冠深层红区禁区外，重点演示第 5 区“铆钉上方 → 朝向侧翼”：从铆钉正上方朝向最宽侧翼施以“少而深”的针刺，可激活下部张力储备，显著提升回弹弹性并增强高频泛音（H₇–H₁₂）。",
