    "s29_b2_badge": "✕ 缺陷1 • 槌冠倾斜（偏击）",
    "s29_notes": "弦槌槌冠与三弦平面的精密对准（第29页）：在动用任何整音针之前，必须确保槌冠与三根同音弦在同一瞬间平行接触。哪怕仅有0.2–0.3 mm的偏斜、弦面高低差或槌冠中凹弦沟，都会造成亚毫秒级的击弦时间差 Δt。在中高次泛音上，这一时间差转化为120°–180°的相位偏移：波峰与波谷正面相消，合成声波坍塌，在泛音列中挖出深深的梳状抵消凹陷。",
    "s30_category": "第五部分：整音 • 弦列贴合与校准",
    "s30_title": "弦列预调校准：挂弦钉、码钉与弦枕栓",
    "s30_subtitle": "“再优秀的弦槌，也只能激发出乐器自身已调校到位的声学潜能！”",
    "s30_kpi": "4 步声学预调",
    "s30_b1_badge": "琴弦贴合校准",
    "s30_c1_title": "下针整音前不可或缺的琴弦贴合与平面校准",
    "s30_c1_desc": "唯有琴弦稳固落座、三弦同高对齐且同度绝对纯净，方能真实诊断弦槌本身的音色状态。",
    "s30_bullet_1": "<strong>1. 挂弦钉与承座清洁：</strong> 清洁铁骨承弦面，由后向前逐一检查挂弦钉处琴弦是否紧贴到位。",
    "s30_bullet_2": "<strong>2. 码钉处敲实贴合：</strong> 用黄铜冲子配合轻锤将琴弦在码钉处稳妥敲贴于弦码，消除假拍杂音。",
    "s30_bullet_3": "<strong>3. 弦枕栓与弦面找平：</strong> 用精密平口钳在弦枕栓后方校准三根同音弦的等距与同一高度平面。",
    "s30_bullet_4": "<strong>4. 同度与制音复核：</strong> 检验弦槌三弦同步触弦、制音头严密止音以及 100% 零拍音的纯净同度。",
    "s30_fact": "🎵 黄金准则：任何针刺整音都无法弥补琴弦虚浮或弦面不平的机械缺陷！",
