    "s30_notes": "第 30 页：结合雅马哈 C3 安装雷诺套件的四张实拍图，讲解动针整音前必不可少的四步弦列预调：1. 挂弦钉与承座清洁检查；2. 黄铜冲子敲实弦码钉贴合；3. 弦枕栓后方校准三弦间距与水平面；4. 复核制音止音与弦槌同步触弦。",
    "s31_category": "第五部分：整音 • 精细与弱音踏板整音",
