    "s32_notes": "第 32 页：交互演示清漆基浸渍工艺：1) 在铆钉区域涂覆可增强弦槌根基，并视漆液种类提升毛毡张力；2) 在木芯上方从侧面微量涂覆可增强高次泛音，但用量过多会粘死通往侧翼的连接并破坏弹簧功能；3) 切勿直接涂在槌尖顶面，否则会产生玻璃般的鼻音化硬度并永久损坏弦槌；4) 时间因素：所有位于木芯上方的涂覆都会随长期弹奏进一步压实；5) 若要提升基音厚度与穿透力，应在中音至低音增加弦槌重量（+m），向高音区减轻重量（-m）。右侧同步展示最高 135 °C 控温热熨与 15 µm 微米砂膜 / 博朗 Series 1 槌冠超精修。",
